def _core_sequence(blocks: list[dict], words: list[str]) -> tuple[str, ...]:
    """The longest contiguous matched word run inside the strongest block —
    the pair's 'formula core'.

    Formulaic reuse (a year-end formula, a battle narrative, a treaty clause)
    makes this tuple all but identical across its occurrences, which is what
    lets the result list collapse 20-30 near-identical rows into one topos.
    """
    best_lo = best_len = 0
    for b in blocks:
        run_start = 0
        run_len = 0
        prev = None
        for wi, _wj in b["matches"]:
            if prev is not None and wi == prev + 1:
                run_len += 1
            else:
                run_len, run_start = 1, wi
            if run_len > best_len:
                best_len, best_lo = run_len, run_start
            prev = wi
    if not best_len:
        return ()
    return tuple(words[best_lo:best_lo + best_len])


def _shingles(s: str, k: int = 4) -> frozenset:
    """Character k-grams — a cheap upper-bound proxy for edit similarity."""
    if len(s) < k:
        return frozenset((s,))
    return frozenset(s[i:i + k] for i in range(len(s) - k + 1))


def cluster_pairs(sigs: list[str], threshold: float = 0.85, min_size: int = 2,
                  max_lev: int = 200000) -> dict:
    """Group pairs that carry the same formulaic core into one topos.

    Pure stdlib — no external clustering library, no numpy. Two stages:
      1. exact duplicate signatures collapse in a single dict pass; verbatim
         formulaic reuse (the dominant case) is fully handled here, in O(n);
      2. survivors are compared only inside a sorted-length window and only
         when their 4-gram overlap makes the threshold reachable, so the
         Levenshtein DP runs on a small candidate set rather than O(n^2) pairs.
    Stage 2 stops at `max_lev` comparisons and reports `truncated` — the cap is
    surfaced to the caller rather than silently dropping work.

    Returns {"clusters": [...], "pair_cluster": [...], "stats": {...}} where
    each cluster is {"id", "size", "members"} with members = pair indices.
    """
    n = len(sigs)
    if n == 0:
        return {"clusters": [], "pair_cluster": [],
                "stats": {"n_pairs": 0, "n_clusters": 0, "n_clustered": 0,
                          "n_singletons": 0, "lev_compares": 0, "truncated": False}}

    parent = list(range(n))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: int, b: int) -> None:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    # stage 1 — exact duplicates
    exact: dict[str, int] = {}
    for i, s in enumerate(sigs):
        j = exact.get(s)
        if j is None:
            exact[s] = i
        else:
            union(i, j)

    # stage 2 — near-duplicates, prefiltered
    by_len = sorted(range(n), key=lambda i: len(sigs[i]))
    sh = [_shingles(sigs[i]) for i in range(n)]
    lev_compares = 0
    truncated = False
    for a in range(n):
        ia = by_len[a]
        la = len(sigs[ia])
        if la < 2:
            continue
        for b in range(a + 1, n):
            ib = by_len[b]
            lb = len(sigs[ib])
            # |la-lb| alone puts the ratio out of reach, and lengths are
            # non-decreasing here -> no further candidate can qualify either.
            if (lb - la) / (la + lb) > 1.0 - threshold:
                break
            if find(ia) == find(ib):
                continue
            ha, hb = sh[ia], sh[ib]
            inter = len(ha & hb)
            if not inter:
                continue
            # Jaccard is an upper bound on edit similarity; cheap rejection
            if 2 * inter / (len(ha) + len(hb)) < threshold * 0.5:
                continue
            if lev_compares >= max_lev:
                truncated = True
                break
            lev_compares += 1
            if levenshtein_ratio(sigs[ia], sigs[ib]) >= threshold:
                union(ia, ib)
        if truncated:
            break

    groups: dict[int, list[int]] = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    clusters = [{"size": len(m), "members": m}
                for m in groups.values() if len(m) >= min_size]
    clusters.sort(key=lambda c: (-c["size"], c["members"][0]))
    for cid, c in enumerate(clusters):
        c["id"] = cid

    pair_cluster = [-1] * n
    for c in clusters:
        for i in c["members"]:
            pair_cluster[i] = c["id"]

    return {
        "clusters": clusters,
        "pair_cluster": pair_cluster,
        "stats": {
            "n_pairs": n,
            "n_clusters": len(clusters),
            "n_clustered": sum(c["size"] for c in clusters),
            "n_singletons": n - sum(c["size"] for c in clusters),
            "lev_compares": lev_compares,
            "truncated": truncated,
        },
    }


