def _sketch(s: str, k: int = 4, bits: int = 4096) -> int:
    """A Bloom sketch of a string's k-grams, packed into one big int.

    `_sketch(a) & _sketch(b) == 0` *proves* the k-gram sets are disjoint:
    a shared k-gram sets its bit in both, and colliding k-grams only ever share
    a bit — they never cancel one. So rejecting on an empty AND can only discard
    pairs the exact set intersection would have discarded too, which makes it
    recall-neutral. It replaces a set intersection with a single C-level int
    AND, which is what makes the O(n^2) scan below affordable.
    """
    v = 0
    for g in _shingles(s, k):
        v |= 1 << (zlib.crc32(g.encode("utf-8")) % bits)
    return v

