1	/* KONI reader — vanilla JS single-page app (hash routing). */
2	"use strict";
3	
4	const API = (p) => "/api" + p;
5	const $view = () => document.getElementById("view");
6	const toast = (msg) => {
7	  const t = document.getElementById("toast");
8	  t.textContent = msg; t.hidden = false;
9	  clearTimeout(toast._t); toast._t = setTimeout(() => (t.hidden = true), 2600);
10	};
11	const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) =>
12	  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
13	const fetchJSON = async (url) => {
14	  const r = await fetch(url);
15	  if (!r.ok) throw new Error("HTTP " + r.status);
16	  return r.json();
17	};
18	
19	/* ---------- settings (font size / line-height / theme) ---------- */
20	const settings = {
21	  load() {
22	    try { return JSON.parse(localStorage.getItem("opentgl") || "{}"); }
23	    catch { return {}; }
24	  },
25	  save(o) { localStorage.setItem("opentgl", JSON.stringify(o)); },
26	};
27	function applySettings() {
28	  const s = settings.load();
29	  const size = s.size ?? 20, lh = s.lh ?? 1.8, theme = s.theme ?? "light";
30	  document.documentElement.style.setProperty("--reader-size", size + "px");
31	  document.documentElement.style.setProperty("--reader-lh", lh);
32	  document.body.dataset.theme = theme;
33	}
34	function changeSize(delta) {
35	  const s = settings.load();
36	  const size = Math.min(34, Math.max(14, (s.size ?? 20) + delta));
37	  settings.save({ ...s, size });
38	  applySettings();
39	}
40	function cycleLineHeight() {
41	  const s = settings.load();
42	  const steps = [1.5, 1.7, 1.8, 2.0, 2.3];
43	  const cur = s.lh ?? 1.8;
44	  const next = steps[(steps.indexOf(cur) + 1) % steps.length] ?? 1.8;
45	  settings.save({ ...s, lh: next });
46	  applySettings();
47	  toast("Line spacing: " + next);
48	}
49	function toggleTheme() {
50	  const s = settings.load();
51	  const theme = (s.theme ?? "light") === "light" ? "dark" : "light";
52	  settings.save({ ...s, theme });
53	  applySettings();
54	}
55	
56	/* ---------- router ---------- */
57	function route() {
58	  const h = location.hash.replace(/^#/, "") || "/";
59	  const [pathPart, queryPart] = h.split("?");
60	  const parts = pathPart.split("/").filter(Boolean); // e.g. ["author","0012"]
61	  const q = {};
62	  if (queryPart) queryPart.split("&").forEach((kv) => {
63	    const [k, v] = kv.split("="); q[k] = decodeURIComponent(v || "");
64	  });
65	  // Mark the current section in the masthead nav before dispatching (the
66	  // render functions below return early, so this cannot live at the end).
67	  const nav = (parts[0] === "compare" || parts[0] === "archaism") ? parts[0] : "search";
68	  document.querySelectorAll(".top-nav a").forEach((a) =>
69	    a.classList.toggle("active", a.dataset.nav === nav));
70	  if (parts[0] === "author" && parts[1]) return renderAuthor(parts[1]);
71	  if (parts[0] === "read" && parts[1] && parts[2]) return renderReader(parts[1], parts[2], parts[3] | 0);
72	  if (parts[0] === "compare") return renderCompare(q);
73	  if (parts[0] === "archaism") return renderArchaism(q);
74	  renderHome();
75	}
76	
77	/* ---------- home / search (client-side filter over all authors) ---------- */
78	let ALL_AUTHORS = null;   // full slim author list, loaded once
79	const PAGE = 150;         // authors shown per "load more" step
80	let _list = null;         // current filtered list
81	let _shown = 0;           // how many of _list are rendered
82	
83	/* Latin -> Greek transliteration (Beta Code-style core), pure JS.
84	   Lets users type Latin without a Greek keyboard and still match polytonic
85	   names: "mhnin" -> "μηνιν", which matches "μῆνιν" via accent-stripped search. */
86	const _GMAP = { a: "α", b: "β", g: "γ", d: "δ", e: "ε", z: "ζ", h: "η", q: "θ",
87	  i: "ι", k: "κ", l: "λ", m: "μ", n: "ν", x: "ξ", o: "ο", p: "π", r: "ρ",
88	  t: "τ", u: "υ", f: "φ", c: "χ", y: "ψ", w: "ω" };
89	function latinToGreek(s) {
90	  s = (s || "").toLowerCase();
91	  let out = "";
92	  for (let i = 0; i < s.length; i++) {
93	    const ch = s[i], next = s[i + 1];
94	    if (ch === "s") out += (next === undefined || !/[a-z]/.test(next)) ? "ς" : "σ";
95	    else if (_GMAP[ch]) out += _GMAP[ch];
96	    else out += ch;
97	  }
98	  return out;
99	}
100	// Accent-insensitive Greek for matching (NFD + drop combining marks; ς -> σ).
101	function stripGreek(s) {
102	  return (s || "").normalize("NFKD").replace(/[̀-ͯ]/g, "")
103	    .replace(/ς/g, "σ").toLowerCase();
104	}
105	
106	function _blob(a) {
107	  const greek = a.author_name_greek || "";
108	  return [a.author_name_latin, greek, a.author_name_english, a.epitheton, a.author_id,
109	          stripGreek(greek)]
110	    .filter(Boolean).join("  ").toLowerCase();
111	}
112	function filterAuthors(all, q) {
113	  q = (q || "").trim().toLowerCase();
114	  if (!q) return all.slice(); // sorted by id already
115	  // Build alternate queries: Latin->Greek, and accent-stripped forms, so that
