def work_freq(sections: list[dict]) -> dict:
    """Word frequencies over a work's FULL text.

    The caller MUST pass unwindowed units — `texts.section_texts(aid, wid,
    window=False)`. The engine's comparison windows overlap by UNIT_OVERLAP
    words, so counting over them double-counts every boundary by a fraction
    that depends on each unit's length and therefore does NOT cancel between
    two works; it would inflate the rates of whichever work has longer leaves.

    Returns {"counts": Counter[norm_word], "total": int, "display": {norm: orig},
             "caps": Counter[norm_word]} where `display` keeps the first original
    (accented) spelling seen, so a row can be shown to a reader as it actually
    appears in the text, and `caps` counts the occurrences whose ORIGINAL
    spelling was capitalized — the evidence for the proper-noun filter. Note
    that accents are dropped by `normalize` but case is not, so the two pieces
    of evidence must be collected separately, from the raw token.
    """
    counts: Counter = Counter()
    caps: Counter = Counter()
    display: dict[str, str] = {}
    for s in sections:
        for w in words(s.get("text", "")):
            n = normalize(w)
            if not n:
                continue
            counts[n] += 1
            if w[:1].isupper():
                caps[n] += 1
            if n not in display:
                display[n] = w
    return {"counts": counts, "total": sum(counts.values()),
            "display": display, "caps": caps}

