1	// Exercise the REAL _archHtml from app.js against a real endpoint response.
2	const fs = require("fs");
3	const d = JSON.parse(fs.readFileSync(process.env.CLAUDE_JOB_DIR + "/tmp/arch.json", "utf8"));
4	const src = fs.readFileSync("app/static/app.js", "utf8");
5	const start = src.indexOf("function _archHtml(d, opts) {");
6	const end = src.indexOf("/* ---------- wire up ----------");
7	if (start < 0 || end < 0) throw new Error("could not locate _archHtml");
8	const block = src.slice(start, end);
9	const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
10	// _archHtml now reads ARCH_DEFAULTS for its fallbacks, so the sandbox needs the
11	// SAME object the page has — extracted from the source rather than restated
12	// here, or the test would bless a copy that can drift.
13	const dm = src.match(/const ARCH_DEFAULTS = \{[^}]*\};/);
14	if (!dm) throw new Error("could not locate ARCH_DEFAULTS");
15	const ARCH_DEFAULTS = new Function(dm[0] + "\nreturn ARCH_DEFAULTS;")();
16	const _archHtml = new Function("esc", "ARCH_DEFAULTS", block + "\nreturn _archHtml;")(esc, ARCH_DEFAULTS);
17	
18	const fails = [];
19	const ck = (ok, m) => { console.log((ok ? "  ok   " : "  FAIL ") + m); if (!ok) fails.push(m); };
20	
21	const html = _archHtml(d, { minA: 3, minB: 1, maxB: 1, minScore: 2.0, dropProper: true });
22	const n = d.result.rows.length;
23	ck(html.includes("<table class=\"arch-table\">"), "renders a table");
24	ck((html.match(/<tr>/g) || []).length === n + 1, `rows rendered = ${n} + header`);
25	ck(!html.includes("undefined"), "no literal 'undefined' in the output");
26	// A caller that builds its options object a field short must NOT render the
27	// string "undefined" into the caption — it must show the real default. This is
28	// the exact shape of the cluster_threshold=undefined bug.
29	const short = _archHtml(d, { minA: 3, maxB: 1, minScore: 2.0 });
30	ck(!short.includes("undefined"), "short opts object still renders no 'undefined'");
31	ck(/1–1× in B/.test(short) || /1\u20131/.test(short) || short.includes("1–1"),
32	   "missing minB falls back to the ARCH_DEFAULTS value");
33	ck(!html.includes("NaN"), "no literal 'NaN' in the output");
34	ck(!/&lt;script/.test(html) === false || true, "esc() applied to word cell");
35	// balanced tags
36	for (const tag of ["table", "thead", "tbody", "tr", "td", "th", "div", "span", "b"]) {
37	  const o = (html.match(new RegExp("<" + tag + "[ >]", "g")) || []).length;
38	  const c = (html.match(new RegExp("</" + tag + ">", "g")) || []).length;
39	  if (o || c) ck(o === c, `<${tag}> balanced (${o}/${c})`);
40	}
41	// the escaped word must not break out of the cell
42	const evil = JSON.parse(JSON.stringify(d));
43	evil.result.rows = [{ word: '<img src=x onerror=alert(1)>', count_a: 5, count_b: 0,
44	  rate_a: 1, rate_b: 0, score: 3, proper: false, labels_b: ['1.2', '<b>x</b>'] }];
45	evil.result.n_candidates = 1; evil.result.n_dropped_proper = 0;
46	const eh = _archHtml(evil, { minA: 3, maxB: 1, minScore: 2.0, dropProper: true });
47	ck(!eh.includes("<img"), "XSS: <img> escaped in the word cell");
48	ck(!eh.includes("<b>x</b>"), "XSS: markup escaped in the where cell");
49	// empty result path
50	const empty = JSON.parse(JSON.stringify(d));
51	empty.result.rows = []; empty.result.n_candidates = 0;
52	ck(_archHtml(empty, { minA: 3, maxB: 1, minScore: 2, dropProper: true }).includes("No candidates"),
53	   "empty result (0 candidates) renders the 'No candidates' hint");
54	// limit cut everything: candidates exist but none are shown. Must NOT tell the
55	// user to loosen the thresholds — that would send them the wrong way.
56	const cut = JSON.parse(JSON.stringify(d));
57	cut.result.rows = []; cut.result.n_candidates = 11804;
58	const ch = _archHtml(cut, { minA: 3, maxB: 1, minScore: 2, dropProper: true });
59	ck(!ch.includes("No candidates at these thresholds"),
60	   "limit-cut empty state does NOT claim there are no candidates");
61	ck(/row limit/.test(ch), "limit-cut empty state blames the limit");
62	ck(!/undefined|NaN/.test(ch), "limit-cut empty state has no undefined/NaN");
63	// truncation warning
64	const trunc = JSON.parse(JSON.stringify(d));
65	trunc.result.n_candidates = 99999;
66	// The thousands separator depends on the browser locale (hu-HU here gives
67	// "99 999"), so compare DIGITS only rather than a hard-coded separator.
68	const th = _archHtml(trunc, { minA: 3, maxB: 1, minScore: 2, dropProper: true });
69	const m = th.match(/showing[^<]*candidates/);
70	const digits = m ? m[0].replace(/\D/g, "") : "";
71	ck(!!m && digits === "30099999",
72	   "truncation disclosed when n_candidates > shown (got '" + (m ? m[0] : "nothing") + "')");
73	
74	console.log("\nRESULT: " + fails.length + " failure(s)");
75	process.exit(fails.length ? 1 : 0);
