50	ck(m._evLociHtml(none, "ξυμμαχία").includes("no occurrences"),
51	   "empty side has its own message");
52	
53	// --- ngrams ---------------------------------------------------------------
54	const nh = m._evNgramsHtml(ng, "ξυμμαχία");
55	ck(nh.includes("<table class=\"arch-table\">"), "n-gram panel renders a table");
56	ck((nh.match(/<tr>/g) || []).length === ng.contrast.rows.length + 1,
57	   `n-gram rows = ${ng.contrast.rows.length} + header`);
58	ck(nh.includes("switch to " + (ng.n === 2 ? "3" : "2") + "-grams"), "gram size toggle");
59	ck(nh.includes("occurrences"), "back to the occurrences");
60	// The rates must divide by the WORKS' totals, and the panel must say so. The
61	// thousands separator is locale-dependent (and Node here uses a NARROW NO-BREAK
62	// SPACE), so match the digit groups with a separator-tolerant pattern rather
63	// than a hard-coded string.
64	const grouped = (n) => new RegExp(String(n).replace(/\B(?=(\d{3})+(?!\d))/g, "\\D{0,3}"));
65	ck(grouped(ng.n_a).test(nh), "A word count stated as the denominator");
66	ck(!nh.includes("undefined") && !nh.includes("NaN"), "n-gram panel: no undefined/NaN");
67	// Empty case has its own explanation, and does not advise lowering min_a.
68	const emptyNg = JSON.parse(JSON.stringify(ng));
69	emptyNg.contrast.rows = [];
70	const eh = m._evNgramsHtml(emptyNg, "ξυμμαχία");
71	ck(eh.includes("No phrase"), "empty n-gram table has its own message");
72	ck(/noise, not phraseology/.test(eh), "empty state explains why raising min_a is wrong");
73	// The printed spelling comes from `display`, the pooled one from `gram`.
74	const mixed = JSON.parse(JSON.stringify(ng));
75	mixed.contrast.rows = [{ gram: ["η", "συμμαχια"], display: ["ἡ", "ξυμμαχία"],
76	  key: "συμμαχια", count_a: 7, count_b: 0, rate_a: 0.047, rate_b: 0.0, score: 4.5 }];
77	const mh = m._evNgramsHtml(mixed, "ξυμμαχία");
78	ck(mh.includes("ἡ ξυμμαχία"), "prints A's spelling via `display`");
79	ck(!/>\s*η συμμαχια\s*</.test(mh), "does not print the pooled key as the phrase");
80	
81	// --- parallel -------------------------------------------------------------
82	const ph = m._evParallelHtml(par, "ξυμμαχία");
83	ck(ph.includes("ev-parallel"), "parallel panel renders a ranked list");
84	ck((ph.match(/<li>/g) || []).length === par.result.hits.length,
85	   `parallel items = ${par.result.hits.length}`);
86	ck(ph.includes("ev-score"), "each parallel carries its score");
87	ck(ph.includes("shared:"), "shared n-grams are shown as evidence");
88	ck(ph.includes("ev-shared") && ph.includes("<b class=\"greek\">"),
89	   "the 3-grams are distinguished from the 2-grams");
90	ck(ph.includes(par.result.n_scored.toLocaleString ? String(par.result.n_scored) : ""),
91	   "scored-sentence count disclosed");
92	ck(ph.includes("dropped for sharing"), "the min_shared bar is explained");
93	// The anchor is echoed so the panel says what it is parallel TO.
94	ck(ph.includes(esc(par.anchor.hit)), "anchor word shown");
95	ck(!ph.includes("undefined") && !ph.includes("NaN"), "parallel panel: no undefined/NaN");
96	// No hits: explain the bar rather than showing an empty list.
97	const nohit = JSON.parse(JSON.stringify(par));
98	nohit.result.hits = [];
99	ck(m._evParallelHtml(nohit, "ξυμμαχία").includes("No sentence"),
100	   "empty parallel result has its own message");
101	// An over-long-skip count appears only when nonzero.
102	const skip = JSON.parse(JSON.stringify(par));
103	skip.result.n_skipped_long = 7;
104	ck(m._evParallelHtml(skip, "ξυμμαχία").includes("skipped as over-long"),
105	   "over-long skips disclosed when nonzero");
106	ck(!ph.includes("skipped as over-long"), "no skip note when nothing was skipped");
107	
108	// --- escaping and balance -------------------------------------------------
109	const evil = JSON.parse(JSON.stringify(loci));
110	evil.work_a.hits[key] = [{ label: "<img src=x>", index: 0, before: [],
111	  hit: "<b>h</b>", after: [], marked: ["<i>m</i>"], pooled: "x" }];
112	evil.work_a.n_hits[key] = 1; evil.work_a.truncated[key] = false;
113	const xh = m._evLociHtml(evil, "<script>");
114	ck(!xh.includes("<img") && !xh.includes("<script>"), "XSS: word and label escaped");
115	ck(!xh.includes("<b>h</b>") && !xh.includes("<i>m</i>"), "XSS: hit and marked escaped");
116	for (const [name, h] of [["loci", lh], ["ngrams", nh], ["parallel", ph]]) {
117	  for (const tag of ["div", "span", "ol", "li", "table", "thead", "tbody", "tr", "td", "th", "b", "mark", "button", "label"]) {
118	    ck(balanced(h, tag), `${name}: <${tag}> balanced`);
119	  }
120	}
