    seen: set[tuple[str, str]] = set()
    for src, table in (("closed", _CLOSED), ("paradigm", _PARADIGM)):
        for lemma, pos, infl in table.get(form, ()):
            k = (lemma, infl)
            if k not in seen:
                seen.add(k)
                out.append(Analysis(lemma, pos, infl, src, src, ""))
