/* The engine's declared reference corpus, adopted once on the first response.
   Only while the field is still the hardcoded value: a reader who typed their
   own reference must not have it overwritten under them by a later response. */
function _archReconcileReference(ref) {
  const el = document.getElementById("arch-ref");
  if (!el || !ref || !ref.aid || !ref.wid) return;
  const declared = `${ref.aid}/${ref.wid}`;
  if (el.value.trim() === KOINE_DEFAULTS.ref && declared !== KOINE_DEFAULTS.ref) {
    console.warn("archaism: engine's Koine reference differs from the UI default",
                 { ui: KOINE_DEFAULTS.ref, engine: declared });
    el.value = declared;
    KOINE_DEFAULTS.ref = declared;
  }
}

