    `&min_revival=${flt("arch-revival", KOINE_DEFAULTS.min_revival)}` +
    `&ref=${encodeURIComponent(ref)}`;
}
const url = API(`/archaism/${ma[1].padStart(4,"0")}/${ma[2]}/${mb[1].padStart(4,"0")}/${mb[2]}` +
