/* The class vocabulary is the ENGINE's, and its labels carry the definition of
   the label rather than a synonym for it — a class called "archaism" printed
   without its three rate conditions is a verdict the reader cannot check. */
const ARCH_CLASSES = {
  archaism: { label: "archaism", note: "absent from the Koine norm, and the younger author uses it MORE than his own model author" },
  classical: { label: "classical", note: "absent from the Koine norm, but its frequency simply follows the model author's — subject- or model-driven rather than overused" },
  overused: { label: "overused", note: "the younger author's mannerism: he uses it far more than the Koine norm does, but it is not classical vocabulary" },
  avoided: { label: "avoided", note: "the Koine word the younger author shuns: common in the Koine norm, rare in his work" },
  shared: { label: "shared", note: "no divergence from the Koine norm large enough to name" },
};

function _koineHtml(d, opts) {
  const r = d.result, w1 = d.work1, w2 = d.work2;
  const ref = d.reference || r.reference || {};
  const rows = r.rows || [];
  const census = r.census || {};
  const total = r.n_considered || 0;
  const head = `
    <div class="cmp-info">
      <b>${esc(w1.title || w1.aid)}</b> <span class="muted">(A, the model, ${r.n_a.toLocaleString()} words)</span>
      &nbsp;→&nbsp;
      <b>${esc(w2.title || w2.aid)}</b> <span class="muted">(B, the archaizer, ${r.n_b.toLocaleString()} words)</span>
      &nbsp;vs&nbsp;
      <b>${esc(ref.author || ref.aid)}</b> <span class="muted">(C, the Koine norm, ${r.n_c.toLocaleString()} words)</span>
      <br><span class="muted">≥ ${r.params.min_a}× in A; A vs Koine ≥ ${r.params.min_ac}, B vs Koine ≥ ${r.params.min_bc},
      B over A ≥ ${r.params.min_revival} (log2)${opts && opts.dropProper ? ", proper nouns removed" : ""}
      · pooling: ${(r.params.variants || []).join(", ") || "off"}</span>
      ${r.n_dropped_proper ? `<br><span class="muted">${r.n_dropped_proper.toLocaleString()} proper nouns hidden (toggle above to show)</span>` : ""}
      ${(r.n_elided_a || r.n_elided_b || r.n_elided_c) ? `<br><span class="muted">elision fragments excluded: ${r.n_elided_a.toLocaleString()} in A, ${r.n_elided_b.toLocaleString()} in B, ${r.n_elided_c.toLocaleString()} in C</span>` : ""}
      ${r.params.variants_mismatch ? `<br><span class="warn">the three works were not pooled the same way — their counts are not comparable</span>` : ""}
    </div>
    <div class="arch-refnote">
      <b>C = ${esc(ref.work || "")}</b>, ${esc(ref.era || "")}
      ${ref.urn ? `<span class="muted">· ${esc(ref.urn)}</span>` : ""}
      ${ref.why ? `<br><span class="muted">${esc(ref.why)}</span>` : ""}
    </div>`;
  if (!rows.length) {
    return head + `<div class="reader-empty">No words at these thresholds.</div>`;
  }
  /* The census first: it is the part of the finding a row limit cannot cut, and
     the whole point of the report is that the CLASS MIX — not the top row — is
     what distinguishes archaizing from vocabulary attrition. */
  const badges = Object.keys(ARCH_CLASSES).map((k) => {
    const n = census[k] || 0;
    return `<span class="arch-class arch-class-${k}" title="${esc(ARCH_CLASSES[k].note)}"
      >${esc(ARCH_CLASSES[k].label)} <b>${n.toLocaleString()}</b>${
      total ? ` <span class="muted">${(100 * n / total).toFixed(1)}%</span>` : ""}</span>`;
  }).join(" ");
  const legend = `<div class="arch-census"><span class="picker-cap">classes over all
    ${total.toLocaleString()} words with ≥ ${r.params.min_a} occurrences in A</span><br>${badges}
    ${r.n_candidates_hidden ? "" : ""}</div>`;
  const split = (x) => !x.variants || !x.variants.length ? "" :
    `<div class="arch-vsplit">${x.variants.map((v) =>
      `<span class="${v.marked ? "marked" : "muted"}">${esc(v.form)} ${v.count_a}/${v.count_b}</span>`
    ).join(" · ")}</div>`;
  const body = rows.map((x) => `
    <tr>
      <td class="arch-word" data-arch-word="${esc(x.word)}" title="click for the occurrences">${esc(x.word)}${split(x)}</td>
      <td><span class="arch-class arch-class-${x.class}" title="${esc((ARCH_CLASSES[x.class] || {}).note || "")}">${esc((ARCH_CLASSES[x.class] || {}).label || x.class)}</span></td>
      <td class="num">${x.count_a}</td>
      <td class="num">${x.rate_a.toFixed(2)}</td>
      <td class="num">${x.count_b}</td>
      <td class="num">${x.rate_b.toFixed(2)}</td>
      <td class="num${x.count_c === 0 ? " strong" : ""}">${x.count_c}</td>
      <td class="num">${x.rate_c.toFixed(2)}</td>
      <td class="num muted">${x.score_ac.toFixed(2)}</td>
      <td class="num muted">${x.score_bc.toFixed(2)}</td>
      <td class="num strong">${x.score_ab.toFixed(2)}</td>
      <td class="arch-mark">${(x.marked_b || []).map((m) =>
        `<span class="arch-tag" title="B writes this word with the marked (Attic) spelling for rule ${esc(m)}">${esc(m)}</span>`).join("") || '<span class="muted">—</span>'}</td>
      <td class="arch-where">${esc((x.labels_b || []).slice(0, 3).join(", "))}${
        (x.labels_b || []).length > 3 ? ` <span class="muted">+${x.labels_b.length - 3}</span>` : ""}</td>
    </tr>`).join("");
  return head + legend + `
    <table class="arch-table arch-table-koine">
      <thead><tr>
        <th>word</th><th>class</th>
        <th class="num" title="occurrences in the model author">A ×</th>
        <th class="num" title="per 1000 words in the model author">A /1k</th>
        <th class="num" title="occurrences in the archaizer">B ×</th>
        <th class="num" title="per 1000 words in the archaizer">B /1k</th>
        <th class="num" title="occurrences in the Koine norm">C ×</th>
        <th class="num" title="per 1000 words in the Koine norm">C /1k</th>
        <th class="num" title="A's rate against the Koine norm (log2)">A/K</th>
        <th class="num" title="B's rate against the Koine norm (log2)">B/K</th>
        <th class="num" title="B's rate against the model author's — negative means B uses it MORE (log2)">B/A</th>
        <th>marked in B</th>
        <th>where in B</th>
      </tr></thead>
      <tbody>${body}</tbody>
    </table>
    <div id="arch-evidence" class="arch-evidence"></div>
    <div class="cmp-info"><span class="muted">These are candidates with their
    evidence attached, not findings. The class rests on three rate ratios and
    nothing else, and one confound survives it: a word the archaizer dwells on
    more than his model does <em>because his subject demands it</em> — Carthage,
    sieges, rivers — is admitted to <em>archaism</em> exactly like a genuine
    revival. The <em>marked in B</em> column is the evidence that separates the
    two by inspection: the survivors that are grammatical and marked are the
    revivals, the ones that are lexical and unmarked are the subject.</span></div>`;
}

