def _compose(base: str, marks: list) -> str:
    """A base plus its combining marks, NFC-composed.

    Marks are emitted in the order they were read, and the order they were read
    in is whatever the source wrote; NFC reorders them canonically, so
    `a)(/` and `a/)(` both come out as the same single code point.
    """
    if not marks:
        return base
    return unicodedata.normalize("NFC", base + "".join(marks))

