def lookup(form: str) -> dict | None:
    """A form from a text -> a dictionary entry, or None.

    Direct hit first (LSJ's own headword or a form it cites); failing that, the
    form is reduced by `lemmas_pure` and each candidate lemma is looked up. The
    result says which route answered:

        match = "head"   the word IS the headword
        match = "form"   LSJ cites it as an inflected form of this entry
        match = "lemma"  reached through the morphological table

    Nothing is guessed: a form the table cannot reduce and LSJ does not list
    returns None, and the caller shows nothing rather than a wrong gloss.
    """
    word = (form or "").strip()
    if not word:
        return None
    key = normalize(word)
    if not key:
        return None
    built = _load_index()

    if built:
        for mm, how in ((_index, "head"), (_index_forms, "form")):
            nn = mm.get(key)
            if nn:
                entry = _entry(nn, mm is _index and _index.get(key) or 0) \
                    if False else _entry_by_key(nn, key, mm)
                if entry:
                    return {"form": word, "key": key, "match": how,
                            "entry": entry, "analysis": []}

    # Second link: the morphological table. Reported separately because a
    # reduction is a reading, not a fact the dictionary states.
    out = []
    seen = set()
    for a in lemmas_pure.candidates(key):
        lem = normalize(a.lemma)
        if lem in seen:
            continue
        seen.add(lem)
        if not built:
            continue
        nn = _index.get(lem) or _index_forms.get(lem)
        if not nn:
            continue
        entry = _entry_by_key(nn, _index.get(lem) and lem or lem,
                              _index if _index.get(lem) else _index_forms)
        if not entry:
            continue
        out.append((entry, {"lemma": a.lemma, "pos": a.pos, "infl": a.infl,
                            "source": a.source}))
        if len(out) >= 4:
            break
    if out:
        entry, analysis = out[0]
        return {"form": word, "key": key, "match": "lemma", "entry": entry,
                "analysis": [x[1] for x in out]}
    return None


def _entry_by_key(nn: str, key: str, tier: dict) -> dict | None:
    """The entry a tier's index points at, with the index re-read from the
    slice so that a freshly loaded slice is authoritative."""
    data = _slice(nn)
    if data is None:
        return None
    pos = tier is _index and data["index"].get(key) \
        or data.get("index_forms", {}).get(key)
    if pos is None:
        return None
    return _entry(nn, pos)

