1	/* KONI reader — vanilla JS single-page app (hash routing). */
2	"use strict";
3	
4	const API = (p) => "/api" + p;
5	const $view = () => document.getElementById("view");
6	const toast = (msg) => {
7	  const t = document.getElementById("toast");
8	  t.textContent = msg; t.hidden = false;
9	  clearTimeout(toast._t); toast._t = setTimeout(() => (t.hidden = true), 2600);
10	};
11	const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) =>
12	  ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
13	const fetchJSON = async (url) => {
14	  const r = await fetch(url);
15	  if (!r.ok) throw new Error("HTTP " + r.status);
16	  return r.json();
17	};
18	
19	/* ---------- settings (font size / line-height / theme) ---------- */
20	const settings = {
21	  load() {
22	    try { return JSON.parse(localStorage.getItem("opentgl") || "{}"); }
23	    catch { return {}; }
24	  },
25	  save(o) { localStorage.setItem("opentgl", JSON.stringify(o)); },
26	};
27	function applySettings() {
28	  const s = settings.load();
29	  const size = s.size ?? 20, lh = s.lh ?? 1.8, theme = s.theme ?? "light";
30	  document.documentElement.style.setProperty("--reader-size", size + "px");
31	  document.documentElement.style.setProperty("--reader-lh", lh);
