Word click:
```js
function wordAtPoint(x, y) {
  let range = null;
  if (document.caretRangeFromPoint) range = document.caretRangeFromPoint(x, y);
  else if (document.caretPositionFromPoint) { const p = document.caretPositionFromPoint(x,y); if (p) { range = document.createRange(); range.setStart(p.offsetNode, p.offset); } }
  if (!range || range.startContainer.nodeType !== 3) return null;
  const node = range.startContainer, text = node.nodeValue, off = range.startOffset;
  // expand
  const isG = (ch) => GREEK_CH.test(ch);
  let a = off, b = off;
  while (a > 0 && isG(text[a-1])) a--;
  while (b < text.length && isG(text[b])) b++;
  const tok = text.slice(a,b);
  if (!tok || !/[\p{Script=Greek}]/u.test(tok)) return null;
  return {node, start:a, end:b, word:tok};
}
```
Note `GREEK_CH.test("")` — must guard empty.

Highlight active word: wrap range in span.

```js
function _markWord(hit) {
  _unmarkWord();
  try {
    const r = document.createRange();
    r.setStart(hit.node, hit.start); r.setEnd(hit.node, hit.end);
    const s = document.createElement("span");
    s.className = "dict-active";
    r.surroundContents(s);
    _dictActive = s;
  } catch { _dictActive = null; }
}
function _unmarkWord() {
  const s = _dictActive;
  if (!s || !s.isConnected) { _dictActive = null; return; }
  const parent = s.parentNode;
  while (s.firstChild) parent.insertBefore(s.firstChild, s);
  parent.removeChild(s);
  parent.normalize();
  _dictActive = null;
}
```
Careful: `parent.normalize()` merges text nodes — this invalidates stored annotation ranges but we re-wrap highlights only on render, so fine. However normalize() would also merge the highlight spans of annotations if we merged adjacent text... normalize only merges adjacent *text* nodes, not elements. Fine.

But careful: annotation highlight spans (`.ann-mark`) also exist. Clicking on a word inside an ann-mark: caretRangeFromPoint returns the text node inside the ann-mark span; expansion stays within that node; surroundContents within a single text node works even if parent is a span. Good.

