            <div id="sources" class="src-list"><span class="spinner">Searching sources…</span></div>
          </details>
          ${textArea}
        </section>
      </div>
      ${meta.has_text ? DRAWER_HTML : ""}
      ${meta.has_text ? POPOVER_HTML : ""}`;
    loadSources(aid, wid);
    if (meta.has_text) {
      _unmarkWord();
      readerState = {
        aid, wid, sections: meta.sections, cur: null,
        title: titleLat, title_greek: w.title_greek || "",
        urn: w.cts_urn || "", edition: meta.edition || w.edition || "",
        author: author.author_name_latin || aid,
        label: new Map(meta.sections.map((s) => [s.index, s.label])),
      };
      _wireReader();
      const first = idx && meta.sections.some((s) => s.index === idx) ? idx : (meta.sections[0]?.index ?? 0);
      loadSection(aid, wid, first);
    }
  } catch (e) {
    $view().innerHTML = `<div class="reader-empty">Error: ${esc(e.message)}</div>`;
  }
}

