/* ---------- reader: dictionary, annotations, export ----------
   Everything the reader adds lives here. Three rules hold throughout:

   1. The client never re-implements the server. The dictionary key, the
      variant pooling and the occurrence count all come from /api/lexicon;
      this file only draws what comes back.
   2. Nothing is fetched that is not asked for. The LSJ manifest is read on the
      first word click, the whole work on the first "whole work" export.
   3. An annotation is anchored to the text it quotes, not to an offset. If the
      edition changes the highlight simply stops matching; the note survives and
      is still listed and exported. */

const DRAWER_HTML = `
      <aside id="drawer" class="drawer" hidden>
        <div class="drawer-tabs">
          <button class="dtab active" type="button" data-tab="dict">Dictionary</button>
          <button class="dtab" type="button" data-tab="notes">Notes <span id="ann-count"></span></button>
          <button class="ev-close" type="button" id="drawer-close">close</button>
        </div>
        <div id="drawer-body" class="drawer-body"></div>
      </aside>`;

const _GREEK = /[\p{Script=Greek}\p{M}]/u;

/* ---- the drawer ---- */
function _drawer() { return document.getElementById("drawer"); }

function _openDrawer(tab) {
  const d = _drawer();
  if (!d) return;
  d.hidden = false;
  if (tab) _drawerTab(tab);
  else _drawerTab(d.querySelector(".dtab.active")?.dataset.tab || "dict");
}

function _closeDrawer() {
  const d = _drawer();
  if (d) d.hidden = true;
}

function _drawerTab(tab) {
  const d = _drawer();
  if (!d) return;
  d.querySelectorAll(".dtab").forEach((b) => b.classList.toggle("active", b.dataset.tab === tab));
  if (tab === "notes") _renderNotes();
  else if (!d.dataset.dictShown) _drawerBody(`<div class="drawer-hint">Click a word in the text to look it up.</div>`), (d.dataset.dictShown = "1");
}

function _drawerBody(html) {
  const b = document.getElementById("drawer-body");
  if (b) b.innerHTML = html;
}

/* ---- word under the cursor ---- */
function _wordAt(x, y) {
  let range = null;
  if (document.caretRangeFromPoint) range = document.caretRangeFromPoint(x, y);
  else if (document.caretPositionFromPoint) {
    const p = document.caretPositionFromPoint(x, y);
    if (p) { range = document.createRange(); range.setStart(p.offsetNode, p.offset); }
  }
  if (!range || range.startContainer.nodeType !== 3) return null;
  const node = range.startContainer, text = node.nodeValue, off = range.startOffset;
  const isG = (ch) => !!ch && _GREEK.test(ch);
  let a = off, b = off;
  while (a > 0 && isG(text[a - 1])) a--;
  while (b < text.length && isG(text[b])) b++;
  const word = text.slice(a, b);
  return word ? { node, start: a, end: b, word } : null;
}

let _dictActive = null;
function _markWord(hit) {
  _unmarkWord();
  try {
    const r = document.createRange();
    r.setStart(hit.node, hit.start);
    r.setEnd(hit.node, hit.end);
    const s = document.createElement("span");
    s.className = "dict-active";
    r.surroundContents(s);
    _dictActive = s;
  } catch { _dictActive = null; }
}
function _unmarkWord() {
  const s = _dictActive;
  _dictActive = null;
  if (!s || !s.isConnected) return;
  const parent = s.parentNode;
  while (s.firstChild) parent.insertBefore(s.firstChild, s);
  parent.removeChild(s);
  parent.normalize();          // merge the split text nodes back
}

/* ---- the dictionary panel ---- */
let _DICT_INFO = null;
async function _dictInfo() {
  if (!_DICT_INFO) {
    try { _DICT_INFO = await fetchJSON(API("/lexicon/info")); }
    catch { _DICT_INFO = { ready: false }; }
  }
  return _DICT_INFO;
}

async function lookupWord(hit) {
  const st = readerState;
  if (!st) return;
  _markWord(hit);
  _openDrawer("dict");
  const d = _drawer();
  if (d) delete d.dataset.dictShown;
  _drawerBody(`<div class="spinner">Looking up…</div>`);
  const info = await _dictInfo();
  const qs = new URLSearchParams({ word: hit.word, a1: st.aid, w1: st.wid });
  let res;
  try { res = await fetchJSON(API("/lexicon?" + qs)); }
  catch (e) {
    _drawerBody(`<div class="reader-empty">Lookup failed: ${esc(String(e.message || e))}</div>`);
    return;
  }
  if (_drawer() && !_drawer().hidden) _drawerBody(_dictHtml(res, hit.word, info));
}

function _dictHtml(d, form, info) {
  const e = d.entry || {};
  const link = info.link_pattern && e.id
    ? String(info.link_pattern).replace("<id>", encodeURIComponent(e.id)) : "";
  const head = `<div class="dict-head">
      <b class="greek">${esc(e.head || form)}</b>
      ${(e.labels || []).map((l) => `<span class="dict-lab">${esc(l)}</span>`).join("")}
      <button class="ev-close" type="button" id="drawer-close2">close</button>
    </div>`;
  if (!d.found) {
    return `${head}
      <div class="dict-form greek">${esc(form)}</div>
      <p class="dict-miss">Not in the dictionary index.</p>
      <p class="dict-note">${info.ready
        ? "LSJ headwords and the inflected forms it cites were tried, then the morphological table — none of them reached an entry."
        : "The dictionary has not been built yet. " + esc(info.how || "")}</p>
      ${_dictFoot(info)}`;
  }
  // How the form reached the entry is a different statement from what the entry
  // says, and the reader needs both: "λόγου is not a headword" is information.
  const how = d.match === "head"
    ? `<span class="muted">the text's form is the headword</span>`
    : d.match === "form"
      ? `<span class="muted">LSJ cites this form under ${esc(e.head || "")}</span>`
      : `<span class="muted">read as <b class="greek">${esc((d.analysis[0] || {}).lemma || "")}</b>
         ${esc((d.analysis[0] || {}).pos || "")} — a morphological reading, not a dictionary fact</span>`;
  const body = e.gloss
    ? `<div class="dict-gloss">${esc(e.gloss)}</div>`
    : e.note ? `<div class="dict-gloss dict-note greek">${esc(e.note)}</div>`
      : `<div class="dict-gloss dict-note">(no gloss: this entry is a cross-reference)</div>`;
  const forms = (e.forms || []).length
    ? `<div class="ev-cap">forms LSJ cites</div>
       <div class="dict-forms">${e.forms.map((f) => `<span class="greek">${esc(f)}</span>`).join("")}</div>`
    : "";
  const alt = (d.analysis || []).length > 1
    ? `<div class="ev-cap">other readings</div><ul class="dict-alt">${d.analysis.slice(1)
      .map((a) => `<li><span class="greek">${esc(a.lemma)}</span> ${esc(a.pos || "")}
        <span class="muted">${esc(a.infl || "")}${a.source ? " · " + esc(a.source) : ""}</span></li>`).join("")}</ul>`
    : "";
  const occ = (d.occurrences || []).filter((o) => o.count).length
    ? `<div class="ev-cap">in this reader</div><ul class="dict-occ">${d.occurrences
      .map((o) => `<li>${esc(o.title || o.aid + "." + o.wid)}
        <b>${o.count}</b> <span class="muted">tokens equal to <span class="greek">${esc(d.key)}</span> (accents ignored)</span></li>`)
      .join("")}</ul>`
    : "";
  return `${head}
    ${d.match === "head" ? "" : `<div class="dict-form greek">${esc(form)}</div>`}
    <div class="dict-how">${how}</div>
    ${body}
    ${forms}${alt}${occ}
    ${link ? `<div class="dict-out"><a class="src-link" href="${esc(link)}" target="_blank" rel="noopener">
      <span class="src-badge">LSJ</span><span class="src-body"><span class="src-label">Open the full entry in Perseus</span>
      <span class="src-detail">${esc(e.id || "")}</span></span></a></div>` : ""}
    ${_dictFoot(info)}`;
}

function _dictFoot(info) {
  if (!info.attribution) return "";
  return `<details class="dict-src"><summary>source &amp; licence</summary>
    <p>${esc(info.source || "")} — ${esc(info.license || "")}</p>
    <p>${esc(info.attribution)}</p>
    <p class="muted">This build is a modified version of the source: Beta Code transliterated
    to Unicode and reduced to headword, gloss, labels and cited forms for a reading aid.</p>
  </details>`;
}

/* ---- annotations (localStorage, exportable) ---- */
const ANNOT = {
  KEY: "koni.annotations",
  all() {
    try {
      const d = JSON.parse(localStorage.getItem(this.KEY) || "{}");
      return Array.isArray(d.items) ? d.items : [];
    } catch { return []; }
  },
  write(items) {
    try { localStorage.setItem(this.KEY, JSON.stringify({ version: 1, items })); }
    catch (e) { toast("Could not save (storage full?)"); }
  },
  forWork(aid, wid) { return this.all().filter((a) => a.aid === aid && a.wid === wid); },
  add(rec) { const it = this.all(); it.push(rec); this.write(it); },
  remove(id) { this.write(this.all().filter((a) => a.id !== id)); },
  update(id, patch) {
    this.write(this.all().map((a) => (a.id === id ? { ...a, ...patch, modified: new Date().toISOString() } : a)));
  },
};

function _annId() {
  return "a" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function _refreshCount() {
  const st = readerState;
  const n = st ? ANNOT.forWork(st.aid, st.wid).length : 0;
  ["ann-count"].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.textContent = n ? `(${n})` : "";
  });
  document.querySelectorAll("#ann-open .ann-dot").forEach((el) => el.remove());
}

/* ---- the selection → annotate flow ---- */
function _selQuote() {
  const sel = document.getSelection();
  if (!sel || sel.isCollapsed || !sel.rangeCount) return null;
  const range = sel.getRangeAt(0);
  const text = document.getElementById("text");
  if (!text || !text.contains(range.commonAncestorContainer)) return null;
  const frag = range.cloneContents();
  frag.querySelectorAll?.(".lnum").forEach((n) => n.remove());   // line numbers are not the text
  const quote = (frag.textContent || "").replace(/\s+/g, " ").trim();
  if (quote.length < 2) return null;
  let el = range.startContainer.nodeType === 3 ? range.startContainer.parentNode : range.startContainer;
  while (el && el !== text && !(el.dataset && el.dataset.bi != null)) el = el.parentNode;
  const bi = el && el !== text && el.dataset ? el.dataset.bi : null;
  const rect = range.getBoundingClientRect();
  return { quote, bi, rect };
}

let _annBtn = null;
function _showAnnBtn(sel) {
  if (!_annBtn) {
    _annBtn = document.createElement("button");
    _annBtn.type = "button";
    _annBtn.id = "ann-btn";
    _annBtn.className = "ann-btn";
    _annBtn.textContent = "✎ annotate";
    document.body.appendChild(_annBtn);
  }
  _annBtn.dataset.bi = sel.bi == null ? "" : sel.bi;
  _annBtn._quote = sel.quote;
  const w = 110, vw = window.innerWidth;
  const top = sel.rect.top - 34 < 8 ? sel.rect.bottom + 8 : sel.rect.top - 34;
  _annBtn.style.top = Math.round(top) + "px";
  _annBtn.style.left = Math.round(Math.min(Math.max(8, sel.rect.left), vw - w - 8)) + "px";
  _annBtn.hidden = false;
}

function _hideAnnBtn() { if (_annBtn) _annBtn.hidden = true; }

let _pop = null;
function _popover() {
  if (!_pop) {
    _pop = document.createElement("div");
    _pop.id = "ann-pop";
    _pop.className = "ann-pop";
    _pop.hidden = true;
    _pop.innerHTML = `
      <div class="ann-quote greek" id="ann-quote"></div>
      <textarea id="ann-note" rows="3" placeholder="note on this passage…"></textarea>
      <input id="ann-tags" type="text" placeholder="tags, comma separated (e.g. hapax, crux)">
      <div class="ann-actions">
        <button class="tool-btn" type="button" id="ann-save">save note</button>
        <button class="tool-btn" type="button" id="ann-cancel">cancel</button>
        <span class="muted" id="ann-err"></span>
      </div>`;
    document.body.appendChild(_pop);
  }
  return _pop;
}

function _openPopover(quote, bi, rect, editId) {
  const p = _popover();
  p.dataset.bi = bi == null ? "" : bi;
  p.dataset.edit = editId || "";
  document.getElementById("ann-quote").textContent = quote;
  document.getElementById("ann-note").value = "";
  document.getElementById("ann-tags").value = "";
  document.getElementById("ann-err").textContent = "";
  if (editId) {
    const a = ANNOT.all().find((x) => x.id === editId);
    if (a) {
      document.getElementById("ann-note").value = a.note || "";
      document.getElementById("ann-tags").value = (a.tags || []).join(", ");
    }
  }
  p.hidden = false;
  if (rect) {
    const h = 240, vh = window.innerHeight;
    const top = rect.bottom + 10 + h > vh ? Math.max(8, rect.top - h - 10) : rect.bottom + 10;
    p.style.top = Math.round(top) + "px";
    p.style.left = Math.round(Math.min(Math.max(8, rect.left), window.innerWidth - p.offsetWidth - 12)) + "px";
  }
  document.getElementById("ann-note").focus();
}

function _closePopover() { if (_pop) _pop.hidden = true; }

function _saveAnnotation() {
  const st = readerState, p = _popover();
  if (!st) return;
  const note = document.getElementById("ann-note").value.trim();
  const tags = document.getElementById("ann-tags").value.split(",").map((t) => t.trim()).filter(Boolean);
  const editId = p.dataset.edit;
  if (!note && !tags.length) {
    document.getElementById("ann-err").textContent = "a note or a tag is needed";
    return;
  }
  if (editId) {
    ANNOT.update(editId, { note, tags });
  } else {
    ANNOT.add({
      id: _annId(), aid: st.aid, wid: st.wid,
      section: st.cur ? st.cur.idx : null,
      section_label: st.cur ? (st.label.get(st.cur.idx) || "") : "",
      bi: p.dataset.bi === "" ? null : +p.dataset.bi,
      quote: document.getElementById("ann-quote").textContent,
      note, tags,
      work: st.title, urn: st.urn,
      created: new Date().toISOString(), modified: null,
    });
  }
  _closePopover();
  _unmarkWord();
  document.getSelection()?.removeAllRanges();
  _hideAnnBtn();
  _paintSection();
  _refreshCount();
  toast(editId ? "Note updated." : "Note saved.");
  if (_drawer() && !_drawer().hidden && _drawer().querySelector(".dtab.active")?.dataset.tab === "notes") _renderNotes();
}

/* ---- highlights: quote → the text the quote came from ----
   Anchoring on the quote rather than on a character offset means the highlight
   cannot drift into the wrong words if the edition changes — it either matches
   or it does not. The block is searched with whitespace collapsed, because the
   browser's selection text and the DOM text disagree about newlines. */
function _blockTextNodes(el) {
  const out = [];
  const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => (n.parentNode?.classList?.contains("lnum")
      ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT),
  });
  let n;
  while ((n = w.nextNode())) out.push(n);
  return out;
}

function _collapse(s) {
  const str = [];
  const map = [];
  let sp = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (/\s/.test(ch)) { sp = true; continue; }
    if (sp && str.length) { str.push(" "); map.push(i); }
    sp = false;
    str.push(ch);
    map.push(i);
  }
  return { str: str.join(""), map };
}

function _wrapQuote(block, quote, id) {
  const nodes = _blockTextNodes(block);
  if (!nodes.length) return false;
  const raw = nodes.map((n) => n.nodeValue).join("");
  const hay = _collapse(raw), needle = _collapse(quote);
  const idx = hay.str.indexOf(needle.str);
  if (idx < 0) return false;
  const start = hay.map[idx];
  const last = needle.str[needle.str.length - 1];
  const end = hay.map[idx + needle.str.length - 1] + (raw.codePointAt(hay.map[idx + needle.str.length - 1]) > 0xffff ? 2 : 1);
  void last;
  // Split into per-node sub-ranges: a range inside one text node always wraps
  // (surroundContents throws only when it would cut an element in half).
  let pos = 0;
  const jobs = [];
  for (const n of nodes) {
    const len = n.nodeValue.length;
    const s = Math.max(start - pos, 0), e = Math.min(end - pos, len);
    if (s < e) jobs.push([n, s, e]);
    pos += len;
  }
  jobs.reverse().forEach(([n, s, e]) => {
    const r = document.createRange();
    r.setStart(n, s);
    r.setEnd(n, e);
    const sp = document.createElement("span");
    sp.className = "ann-mark";
    sp.dataset.annId = id;
    sp.title = "annotated — click for the note";
    r.surroundContents(sp);
  });
  return true;
}

function _paintSection() {
  const text = document.getElementById("text");
  const cur = readerState && readerState.cur;
  if (!text || !cur) return;
  text.innerHTML = cur.sec.blocks.map(renderBlock).join("") || `<p class="reader-empty">(empty)</p>`;
  _applyAnnHighlights();
}

function _applyAnnHighlights() {
  const st = readerState;
  const text = document.getElementById("text");
  if (!st || !st.cur || !text) return;
  const items = ANNOT.forWork(st.aid, st.wid).filter((a) => a.section === st.cur.idx);
  const byBlock = new Map();
  items.forEach((a) => {
    if (a.bi == null) return;
    if (!byBlock.has(a.bi)) byBlock.set(a.bi, []);
    byBlock.get(a.bi).push(a);
  });
  byBlock.forEach((list, bi) => {
    const block = text.querySelector(`[data-bi="${bi}"]`);
    if (!block) return;
    list.sort((a, b) => b.quote.length - a.quote.length);   // longest first: it may contain the shorter
    list.forEach((a) => { try { _wrapQuote(block, a.quote, a.id); } catch { /* never break the text */ } });
  });
}

/* ---- the notes tab ---- */
function _notesHtml() {
  const st = readerState;
  if (!st) return "";
  const items = ANNOT.forWork(st.aid, st.wid);
  const bar = `<div class="ann-bar">
      <button class="tool-btn" type="button" data-ann-exp="json">⤓ JSON</button>
      <button class="tool-btn" type="button" data-ann-exp="md">⤓ Markdown</button>
      <button class="tool-btn" type="button" data-ann-imp="1">⤒ import</button>
      ${items.length ? `<button class="tool-btn danger" type="button" data-ann-clear="1">delete all</button>` : ""}
      <input type="file" id="ann-file" accept=".json,application/json" hidden>
    </div>`;
  if (!items.length) {
    return `${bar}<div class="drawer-hint">No notes on this work yet.
      Select a passage in the text and press <b>✎ annotate</b>.</div>`;
  }
  const groups = new Map();
  items.slice().sort((a, b) => (a.section ?? 1e9) - (b.section ?? 1e9))
    .forEach((a) => {
      const k = a.section ?? -1;
      if (!groups.has(k)) groups.set(k, []);
      groups.get(k).push(a);
    });
  const html = [...groups.entries()].map(([sec, list]) => `
    <div class="ann-group">
      <div class="ev-cap">${sec < 0 ? "unplaced" : esc(list[0].section_label || "section " + sec)}</div>
      ${list.map((a) => `<div class="ann-item" data-ann-id="${esc(a.id)}">
        <div class="ann-q greek" ${a.section != null ? `data-ann-goto="${a.section}"` : ""}
          title="${a.section != null ? "go to this passage" : ""}">“${esc(a.quote)}”</div>
        ${a.note ? `<div class="ann-note-body">${esc(a.note)}</div>` : ""}
        ${(a.tags || []).length ? `<div class="ann-tags">${a.tags.map((t) => `<span class="ann-tag">${esc(t)}</span>`).join("")}</div>` : ""}
        <div class="ann-acts">
          <button class="ann-mini" type="button" data-ann-edit="${esc(a.id)}">edit</button>
          <button class="ann-mini" type="button" data-ann-del="${esc(a.id)}">delete</button>
          <span class="muted">${esc((a.created || "").slice(0, 10))}</span>
        </div>
      </div>`).join("")}
    </div>`).join("");
  return bar + html;
}

function _renderNotes() { _drawerBody(_notesHtml()); }

/* ---- exports ---- */
function _download(name, text, mime) {
  const blob = new Blob([text], { type: (mime || "text/plain") + ";charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = name;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}

function _blocksTxt(blocks) {
  const out = [];
  for (const b of blocks) {
    if (b.kind === "head") out.push("", "## " + b.text, "");
    else if (b.kind === "line") out.push((b.n != null ? String(b.n).padStart(5) : "     ") + "  " + b.text);
    else out.push(b.text, "");
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

function _txtHeader(st, sectionLabel) {
  return [
    "# KONI — exported Greek text",
    "# author: " + (st.author || st.aid) + " (" + st.aid + ")",
    "# work: " + (st.title || st.wid) + (st.title_greek ? " / " + st.title_greek : ""),
    "# urn: " + (st.urn || ""),
    "# edition: " + (st.edition || "(as recorded by the app)"),
    sectionLabel ? "# section: " + sectionLabel : null,
    "# exported: " + new Date().toISOString(),
    "# Line numbers are the edition's. The text is the open edition served by",
    "# /api/text; check the Sources list in the app for the scan or edition it came from.",
  ].filter((x) => x != null).join("\n") + "\n";
}

function _annAppendix(items, label) {
  if (!items.length) return "";
  return "\n\n# ---- annotations (" + label + ") ----\n" + items.map((a) =>
    `# [${a.section_label || a.section}] "${a.quote}"\n#   ${a.note || "(no note)"}`
    + ((a.tags || []).length ? `\n#   tags: ${a.tags.join(", ")}` : "")).join("\n");
}

function exportSection() {
  const st = readerState;
  if (!st || !st.cur) { toast("Nothing loaded yet."); return; }
  const label = st.label.get(st.cur.idx) || String(st.cur.idx);
  const items = ANNOT.forWork(st.aid, st.wid).filter((a) => a.section === st.cur.idx);
  const txt = _txtHeader(st, label) + "\n" + _blocksTxt(st.cur.sec.blocks)
    + _annAppendix(items, "this section") + "\n";
  _download(`koni_${st.aid}.${st.wid}.${st.cur.idx}.txt`, txt);
  toast("Section exported (txt).");
}

async function exportWork() {
  const st = readerState;
  if (!st) return;
  const secs = st.sections.filter((s) => s.block_count);
  if (!secs.length) { toast("This work has no text to export."); return; }
  toast(`Exporting ${secs.length} sections…`);
  const parts = [_txtHeader(st, null)];
  for (let i = 0; i < secs.length; i++) {
    const s = secs[i];
    try {
      const sec = await fetchJSON(API(`/text/${st.aid}/${st.wid}/section/${s.index}`));
      parts.push("\n\n" + "# ===== " + (s.label || s.index) + " =====\n\n" + _blocksTxt(sec.blocks));
    } catch (e) {
      parts.push(`\n\n# ===== ${s.label || s.index} — FAILED: ${e.message} =====`);
    }
    toast(`Exporting… ${i + 1}/${secs.length}`);
  }
  parts.push(_annAppendix(ANNOT.forWork(st.aid, st.wid), "whole work"));
  _download(`koni_${st.aid}.${st.wid}.txt`, parts.join("\n") + "\n");
  toast(`Work exported: ${secs.length} sections.`);
}

function _annItemsForExport() {
  const st = readerState;
  return st ? ANNOT.forWork(st.aid, st.wid) : [];
}

function exportAnnotations(fmt) {
  const st = readerState, items = _annItemsForExport();
  if (!st || !items.length) { toast("No notes to export."); return; }
  const base = `koni_notes_${st.aid}.${st.wid}`;
  if (fmt === "md") {
    const lines = [`# Notes — ${st.title || st.wid}`, "",
      `_${st.author || st.aid} · ${st.urn || ""} · exported ${new Date().toISOString().slice(0, 10)}_`, ""];
    items.slice().sort((a, b) => (a.section ?? 1e9) - (b.section ?? 1e9)).forEach((a) => {
      lines.push(`## ${a.section_label || a.section || "unplaced"}`, "",
        `> ${a.quote}`, "", a.note || "_(no note)_",
        (a.tags || []).length ? `\nTags: ${a.tags.map((t) => "`" + t + "`").join(" ")}` : "", "");
    });
    _download(base + ".md", lines.join("\n"), "text/markdown");
  } else {
    _download(base + ".json", JSON.stringify({
      version: 1, exported: new Date().toISOString(),
      work: { aid: st.aid, wid: st.wid, title: st.title, author: st.author, urn: st.urn },
      items,
    }, null, 1), "application/json");
  }
  toast(`${items.length} notes exported (${fmt.toUpperCase()}).`);
}

function importAnnotations(file) {
  const st = readerState;
  if (!st || !file) return;
  const fr = new FileReader();
  fr.onload = () => {
    let d;
    try { d = JSON.parse(String(fr.result)); }
    catch { toast("Not a JSON file."); return; }
    const items = Array.isArray(d) ? d : (Array.isArray(d.items) ? d.items : []);
    if (!items.length) { toast("No notes in that file."); return; }
    const have = new Set(ANNOT.all().map((a) => a.id));
    let n = 0;
    items.forEach((a) => {
      if (!a || !a.quote) return;
      const rec = {
        id: have.has(a.id) ? _annId() : (a.id || _annId()),
        aid: a.aid || st.aid, wid: a.wid || st.wid,
        section: a.section ?? null, section_label: a.section_label || "",
        bi: a.bi ?? null, quote: a.quote, note: a.note || "",
        tags: Array.isArray(a.tags) ? a.tags : [],
        work: a.work || st.title, urn: a.urn || st.urn,
        created: a.created || new Date().toISOString(), modified: a.modified || null,
      };
      if (have.has(rec.id)) return;
      ANNOT.add(rec);
      have.add(rec.id);
      n++;
    });
    _paintSection();
    _refreshCount();
    _renderNotes();
    toast(n ? `${n} notes imported.` : "Nothing new to import.");
  };
  fr.readAsText(file);
}

/* ---- section stepping and shortcuts ---- */
function _stepSection(dir) {
  const st = readerState;
  if (!st || !st.sections.length) return;
  const i = st.sections.findIndex((s) => s.index === (st.cur ? st.cur.idx : -1));
  const next = st.sections[i < 0 ? 0 : i + dir];
  if (!next) { toast(dir > 0 ? "Last section." : "First section."); return; }
  loadSection(st.aid, st.wid, next.index);
}

function _onKey(e) {
  if (/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName) || e.target.isContentEditable) return;
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  if (e.key === "Escape") {
    _closePopover();
    _hideAnnBtn();
    _unmarkWord();
    _closeDrawer();
    return;
  }
  if (!readerState || !document.getElementById("text")) return;
  if (e.key === "[") { e.preventDefault(); _stepSection(-1); }
  else if (e.key === "]") { e.preventDefault(); _stepSection(1); }
}

function _onTextClick(e) {
  const text = document.getElementById("text");
  if (!text || !text.contains(e.target)) return;
  const mark = e.target.closest?.(".ann-mark");
  const sel = document.getSelection();
  if (sel && !sel.isCollapsed) return;      // selecting, not looking up
  if (mark) {                                // an annotated word: show its note
    const a = ANNOT.all().find((x) => x.id === mark.dataset.annId);
    if (a) {
      _openDrawer("notes");
      const el = _drawer()?.querySelector(`[data-ann-id="${a.id}"]`);
      if (el) { el.scrollIntoView({ block: "center", behavior: "smooth" }); el.classList.add("flash"); setTimeout(() => el.classList.remove("flash"), 1200); }
      return;
    }
  }
  const hit = _wordAt(e.clientX, e.clientY);
  if (hit) lookupWord(hit);
}

function _onMouseUp(e) {
  if (_pop && !_pop.hidden) return;
  if (e.target.closest?.("#ann-btn, #ann-pop, #drawer")) return;
  _hideAnnBtn();
  const sel = _selQuote();
  if (!sel) return;
  if (_drawer()?.contains(e.target)) return;
  _showAnnBtn(sel);
}

function _onDelegateClick(e) {
  const t = e.target;
  const hit = (sel) => t.closest?.(sel);
  if (hit("#exp-sec")) return exportSection();
  if (hit("#exp-work")) return exportWork();
  if (hit("#ann-open")) { _openDrawer("notes"); return; }
  if (hit("#drawer-close") || hit("#drawer-close2")) return _closeDrawer();
  const tab = hit(".dtab");
  if (tab) return _drawerTab(tab.dataset.tab);
  if (hit("#ann-btn")) {
    const b = hit("#ann-btn");
    return _openPopover(b._quote || "", b.dataset.bi, b.getBoundingClientRect());
  }
  if (hit("#ann-cancel")) return _closePopover();
  if (hit("#ann-save")) return _saveAnnotation();
  const exp = hit("[data-ann-exp]");
  if (exp) return exportAnnotations(exp.dataset.annExp);
  const imp = hit("[data-ann-imp]");
  if (imp) return document.getElementById("ann-file")?.click();
  const clr = hit("[data-ann-clear]");
  if (clr) {
    const st = readerState;
    if (!st) return;
    if (!confirm("Delete every note on this work? This cannot be undone.")) return;
    ANNOT.write(ANNOT.all().filter((a) => !(a.aid === st.aid && a.wid === st.wid)));
    _paintSection();
    _refreshCount();
    _renderNotes();
    toast("Notes deleted.");
    return;
  }
  const go = hit("[data-ann-goto]");
  if (go) {
    const idx = +go.dataset.annGoto;
    const st = readerState;
    if (!st) return;
    if (st.cur && st.cur.idx === idx) {
      _drawer()?.querySelector(`[data-ann-id="${go.closest("[data-ann-id]")?.dataset.annId}"]`)
        ?.scrollIntoView({ block: "center", behavior: "smooth" });
    } else loadSection(st.aid, st.wid, idx);
    return;
  }
  const ed = hit("[data-ann-edit]");
  if (ed) {
    const a = ANNOT.all().find((x) => x.id === ed.dataset.annEdit);
    if (a) _openPopover(a.quote, a.bi, ed.getBoundingClientRect(), a.id);
    return;
  }
  const del = hit("[data-ann-del]");
  if (del) {
    const a = ANNOT.all().find((x) => x.id === del.dataset.annDel);
    if (a && confirm("Delete this note?\n\n“" + a.quote.slice(0, 90) + "”")) {
      ANNOT.remove(a.id);
      _paintSection();
      _refreshCount();
      _renderNotes();
      toast("Note deleted.");
    }
    return;
  }
}

document.addEventListener("click", _onDelegateClick);
document.addEventListener("mouseup", _onMouseUp);
document.addEventListener("keydown", _onKey);
document.addEventListener("change", (e) => {
  if (e.target.id === "ann-file" && e.target.files?.[0]) {
    importAnnotations(e.target.files[0]);
    e.target.value = "";
  }
});

toolUseResult.newString:
  return `<p class="para"${bi}>${esc(b.text)}</p>`;
}

/* ---------- reader: dictionary, annotations, export ----------
   Everything the reader adds lives here. Three rules hold throughout:

   1. The client never re-implements the server. The dictionary key, the
      variant pooling and the occurrence count all come from /api/lexicon;
      this file only draws what comes back.
   2. Nothing is fetched that is not asked for. The LSJ manifest is read on the
      first word click, the whole work on the first "whole work" export.
   3. An annotation is anchored to the text it quotes, not to an offset. If the
      edition changes the highlight simply stops matching; the note survives and
      is still listed and exported. */

const DRAWER_HTML = `
      <aside id="drawer" class="drawer" hidden>
        <div class="drawer-tabs">
          <button class="dtab active" type="button" data-tab="dict">Dictionary</button>
          <button class="dtab" type="button" data-tab="notes">Notes <span id="ann-count"></span></button>
          <button class="ev-close" type="button" id="drawer-close">close</button>
        </div>
        <div id="drawer-body" class="drawer-body"></div>
      </aside>`;

const _GREEK = /[\p{Script=Greek}\p{M}]/u;

/* ---- the drawer ---- */
function _drawer() { return document.getElementById("drawer"); }

function _openDrawer(tab) {
  const d = _drawer();
  if (!d) return;
  d.hidden = false;
  if (tab) _drawerTab(tab);
  else _drawerTab(d.querySelector(".dtab.active")?.dataset.tab || "dict");
}

function _closeDrawer() {
  const d = _drawer();
  if (d) d.hidden = true;
}

function _drawerTab(tab) {
  const d = _drawer();
  if (!d) return;
  d.querySelectorAll(".dtab").forEach((b) => b.classList.toggle("active", b.dataset.tab === tab));
  if (tab === "notes") _renderNotes();
  else if (!d.dataset.dictShown) _drawerBody(`<div class="drawer-hint">Click a word in the text to look it up.</div>`), (d.dataset.dictShown = "1");
}

function _drawerBody(html) {
  const b = document.getElementById("drawer-body");
  if (b) b.innerHTML = html;
}

/* ---- word under the cursor ---- */
function _wordAt(x, y) {
  let range = null;
  if (document.caretRangeFromPoint) range = document.caretRangeFromPoint(x, y);
  else if (document.caretPositionFromPoint) {
    const p = document.caretPositionFromPoint(x, y);
    if (p) { range = document.createRange(); range.setStart(p.offsetNode, p.offset); }
  }
  if (!range || range.startContainer.nodeType !== 3) return null;
  const node = range.startContainer, text = node.nodeValue, off = range.startOffset;
  const isG = (ch) => !!ch && _GREEK.test(ch);
  let a = off, b = off;
  while (a > 0 && isG(text[a - 1])) a--;
  while (b < text.length && isG(text[b])) b++;
  const word = text.slice(a, b);
  return word ? { node, start: a, end: b, word } : null;
}

let _dictActive = null;
function _markWord(hit) {
  _unmarkWord();
  try {
    const r = document.createRange();
    r.setStart(hit.node, hit.start);
    r.setEnd(hit.node, hit.end);
    const s = document.createElement("span");
    s.className = "dict-active";
    r.surroundContents(s);
    _dictActive = s;
  } catch { _dictActive = null; }
}
function _unmarkWord() {
  const s = _dictActive;
  _dictActive = null;
  if (!s || !s.isConnected) return;
  const parent = s.parentNode;
  while (s.firstChild) parent.insertBefore(s.firstChild, s);
  parent.removeChild(s);
  parent.normalize();          // merge the split text nodes back
}

/* ---- the dictionary panel ---- */
let _DICT_INFO = null;
async function _dictInfo() {
  if (!_DICT_INFO) {
    try { _DICT_INFO = await fetchJSON(API("/lexicon/info")); }
    catch { _DICT_INFO = { ready: false }; }
  }
  return _DICT_INFO;
}

async function lookupWord(hit) {
  const st = readerState;
  if (!st) return;
  _markWord(hit);
  _openDrawer("dict");
  const d = _drawer();
  if (d) delete d.dataset.dictShown;
  _drawerBody(`<div class="spinner">Looking up…</div>`);
  const info = await _dictInfo();
  const qs = new URLSearchParams({ word: hit.word, a1: st.aid, w1: st.wid });
  let res;
  try { res = await fetchJSON(API("/lexicon?" + qs)); }
  catch (e) {
    _drawerBody(`<div class="reader-empty">Lookup failed: ${esc(String(e.message || e))}</div>`);
    return;
  }
  if (_drawer() && !_drawer().hidden) _drawerBody(_dictHtml(res, hit.word, info));
}

function _dictHtml(d, form, info) {
  const e = d.entry || {};
  const link = info.link_pattern && e.id
    ? String(info.link_pattern).replace("<id>", encodeURIComponent(e.id)) : "";
  const head = `<div class="dict-head">
      <b class="greek">${esc(e.head || form)}</b>
      ${(e.labels || []).map((l) => `<span class="dict-lab">${esc(l)}</span>`).join("")}
      <button class="ev-close" type="button" id="drawer-close2">close</button>
    </div>`;
  if (!d.found) {
    return `${head}
      <div class="dict-form greek">${esc(form)}</div>
      <p class="dict-miss">Not in the dictionary index.</p>
      <p class="dict-note">${info.ready
        ? "LSJ headwords and the inflected forms it cites were tried, then the morphological table — none of them reached an entry."
        : "The dictionary has not been built yet. " + esc(info.how || "")}</p>
      ${_dictFoot(info)}`;
  }
  // How the form reached the entry is a different statement from what the entry
  // says, and the reader needs both: "λόγου is not a headword" is information.
  const how = d.match === "head"
    ? `<span class="muted">the text's form is the headword</span>`
    : d.match === "form"
      ? `<span class="muted">LSJ cites this form under ${esc(e.head || "")}</span>`
      : `<span class="muted">read as <b class="greek">${esc((d.analysis[0] || {}).lemma || "")}</b>
         ${esc((d.analysis[0] || {}).pos || "")} — a morphological reading, not a dictionary fact</span>`;
  const body = e.gloss
    ? `<div class="dict-gloss">${esc(e.gloss)}</div>`
    : e.note ? `<div class="dict-gloss dict-note greek">${esc(e.note)}</div>`
      : `<div class="dict-gloss dict-note">(no gloss: this entry is a cross-reference)</div>`;
  const forms = (e.forms || []).length
    ? `<div class="ev-cap">forms LSJ cites</div>
       <div class="dict-forms">${e.forms.map((f) => `<span class="greek">${esc(f)}</span>`).join("")}</div>`
    : "";
  const alt = (d.analysis || []).length > 1
    ? `<div class="ev-cap">other readings</div><ul class="dict-alt">${d.analysis.slice(1)
      .map((a) => `<li><span class="greek">${esc(a.lemma)}</span> ${esc(a.pos || "")}
        <span class="muted">${esc(a.infl || "")}${a.source ? " · " + esc(a.source) : ""}</span></li>`).join("")}</ul>`
    : "";
  const occ = (d.occurrences || []).filter((o) => o.count).length
    ? `<div class="ev-cap">in this reader</div><ul class="dict-occ">${d.occurrences
      .map((o) => `<li>${esc(o.title || o.aid + "." + o.wid)}
        <b>${o.count}</b> <span class="muted">tokens equal to <span class="greek">${esc(d.key)}</span> (accents ignored)</span></li>`)
      .join("")}</ul>`
    : "";
  return `${head}
    ${d.match === "head" ? "" : `<div class="dict-form greek">${esc(form)}</div>`}
    <div class="dict-how">${how}</div>
    ${body}
    ${forms}${alt}${occ}
    ${link ? `<div class="dict-out"><a class="src-link" href="${esc(link)}" target="_blank" rel="noopener">
      <span class="src-badge">LSJ</span><span class="src-body"><span class="src-label">Open the full entry in Perseus</span>
      <span class="src-detail">${esc(e.id || "")}</span></span></a></div>` : ""}
    ${_dictFoot(info)}`;
}

function _dictFoot(info) {
  if (!info.attribution) return "";
  return `<details class="dict-src"><summary>source &amp; licence</summary>
    <p>${esc(info.source || "")} — ${esc(info.license || "")}</p>
    <p>${esc(info.attribution)}</p>
    <p class="muted">This build is a modified version of the source: Beta Code transliterated
    to Unicode and reduced to headword, gloss, labels and cited forms for a reading aid.</p>
  </details>`;
}

/* ---- annotations (localStorage, exportable) ---- */
const ANNOT = {
  KEY: "koni.annotations",
  all() {
    try {
      const d = JSON.parse(localStorage.getItem(this.KEY) || "{}");
      return Array.isArray(d.items) ? d.items : [];
    } catch { return []; }
  },
  write(items) {
    try { localStorage.setItem(this.KEY, JSON.stringify({ version: 1, items })); }
    catch (e) { toast("Could not save (storage full?)"); }
  },
  forWork(aid, wid) { return this.all().filter((a) => a.aid === aid && a.wid === wid); },
  add(rec) { const it = this.all(); it.push(rec); this.write(it); },
  remove(id) { this.write(this.all().filter((a) => a.id !== id)); },
  update(id, patch) {
    this.write(this.all().map((a) => (a.id === id ? { ...a, ...patch, modified: new Date().toISOString() } : a)));
  },
};

function _annId() {
  return "a" + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function _refreshCount() {
  const st = readerState;
  const n = st ? ANNOT.forWork(st.aid, st.wid).length : 0;
  ["ann-count"].forEach((id) => {
    const el = document.getElementById(id);
    if (el) el.textContent = n ? `(${n})` : "";
  });
  document.querySelectorAll("#ann-open .ann-dot").forEach((el) => el.remove());
}

/* ---- the selection → annotate flow ---- */
function _selQuote() {
  const sel = document.getSelection();
  if (!sel || sel.isCollapsed || !sel.rangeCount) return null;
  const range = sel.getRangeAt(0);
  const text = document.getElementById("text");
  if (!text || !text.contains(range.commonAncestorContainer)) return null;
  const frag = range.cloneContents();
  frag.querySelectorAll?.(".lnum").forEach((n) => n.remove());   // line numbers are not the text
  const quote = (frag.textContent || "").replace(/\s+/g, " ").trim();
  if (quote.length < 2) return null;
  let el = range.startContainer.nodeType === 3 ? range.startContainer.parentNode : range.startContainer;
  while (el && el !== text && !(el.dataset && el.dataset.bi != null)) el = el.parentNode;
  const bi = el && el !== text && el.dataset ? el.dataset.bi : null;
  const rect = range.getBoundingClientRect();
  return { quote, bi, rect };
}

let _annBtn = null;
function _showAnnBtn(sel) {
  if (!_annBtn) {
    _annBtn = document.createElement("button");
    _annBtn.type = "button";
    _annBtn.id = "ann-btn";
    _annBtn.className = "ann-btn";
    _annBtn.textContent = "✎ annotate";
    document.body.appendChild(_annBtn);
  }
  _annBtn.dataset.bi = sel.bi == null ? "" : sel.bi;
  _annBtn._quote = sel.quote;
  const w = 110, vw = window.innerWidth;
  const top = sel.rect.top - 34 < 8 ? sel.rect.bottom + 8 : sel.rect.top - 34;
  _annBtn.style.top = Math.round(top) + "px";
  _annBtn.style.left = Math.round(Math.min(Math.max(8, sel.rect.left), vw - w - 8)) + "px";
  _annBtn.hidden = false;
}

function _hideAnnBtn() { if (_annBtn) _annBtn.hidden = true; }

let _pop = null;
function _popover() {
  if (!_pop) {
    _pop = document.createElement("div");
    _pop.id = "ann-pop";
    _pop.className = "ann-pop";
    _pop.hidden = true;
    _pop.innerHTML = `
      <div class="ann-quote greek" id="ann-quote"></div>
      <textarea id="ann-note" rows="3" placeholder="note on this passage…"></textarea>
      <input id="ann-tags" type="text" placeholder="tags, comma separated (e.g. hapax, crux)">
      <div class="ann-actions">
        <button class="tool-btn" type="button" id="ann-save">save note</button>
        <button class="tool-btn" type="button" id="ann-cancel">cancel</button>
        <span class="muted" id="ann-err"></span>
      </div>`;
    document.body.appendChild(_pop);
  }
  return _pop;
}

function _openPopover(quote, bi, rect, editId) {
  const p = _popover();
  p.dataset.bi = bi == null ? "" : bi;
  p.dataset.edit = editId || "";
  document.getElementById("ann-quote").textContent = quote;
  document.getElementById("ann-note").value = "";
  document.getElementById("ann-tags").value = "";
  document.getElementById("ann-err").textContent = "";
  if (editId) {
    const a = ANNOT.all().find((x) => x.id === editId);
    if (a) {
      document.getElementById("ann-note").value = a.note || "";
      document.getElementById("ann-tags").value = (a.tags || []).join(", ");
    }
  }
  p.hidden = false;
  if (rect) {
    const h = 240, vh = window.innerHeight;
    const top = rect.bottom + 10 + h > vh ? Math.max(8, rect.top - h - 10) : rect.bottom + 10;
    p.style.top = Math.round(top) + "px";
    p.style.left = Math.round(Math.min(Math.max(8, rect.left), window.innerWidth - p.offsetWidth - 12)) + "px";
  }
  document.getElementById("ann-note").focus();
}

function _closePopover() { if (_pop) _pop.hidden = true; }

function _saveAnnotation() {
  const st = readerState, p = _popover();
  if (!st) return;
  const note = document.getElementById("ann-note").value.trim();
  const tags = document.getElementById("ann-tags").value.split(",").map((t) => t.trim()).filter(Boolean);
  const editId = p.dataset.edit;
  if (!note && !tags.length) {
    document.getElementById("ann-err").textContent = "a note or a tag is needed";
    return;
  }
  if (editId) {
    ANNOT.update(editId, { note, tags });
  } else {
    ANNOT.add({
      id: _annId(), aid: st.aid, wid: st.wid,
      section: st.cur ? st.cur.idx : null,
      section_label: st.cur ? (st.label.get(st.cur.idx) || "") : "",
      bi: p.dataset.bi === "" ? null : +p.dataset.bi,
      quote: document.getElementById("ann-quote").textContent,
      note, tags,
      work: st.title, urn: st.urn,
      created: new Date().toISOString(), modified: null,
    });
  }
  _closePopover();
  _unmarkWord();
  document.getSelection()?.removeAllRanges();
  _hideAnnBtn();
  _paintSection();
  _refreshCount();
  toast(editId ? "Note updated." : "Note saved.");
  if (_drawer() && !_drawer().hidden && _drawer().querySelector(".dtab.active")?.dataset.tab === "notes") _renderNotes();
}

/* ---- highlights: quote → the text the quote came from ----
   Anchoring on the quote rather than on a character offset means the highlight
   cannot drift into the wrong words if the edition changes — it either matches
   or it does not. The block is searched with whitespace collapsed, because the
   browser's selection text and the DOM text disagree about newlines. */
function _blockTextNodes(el) {
  const out = [];
  const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => (n.parentNode?.classList?.contains("lnum")
      ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT),
  });
  let n;
  while ((n = w.nextNode())) out.push(n);
  return out;
}

function _collapse(s) {
  const str = [];
  const map = [];
  let sp = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (/\s/.test(ch)) { sp = true; continue; }
    if (sp && str.length) { str.push(" "); map.push(i); }
    sp = false;
    str.push(ch);
    map.push(i);
  }
  return { str: str.join(""), map };
}

function _wrapQuote(block, quote, id) {
  const nodes = _blockTextNodes(block);
  if (!nodes.length) return false;
  const raw = nodes.map((n) => n.nodeValue).join("");
  const hay = _collapse(raw), needle = _collapse(quote);
  const idx = hay.str.indexOf(needle.str);
  if (idx < 0) return false;
  const start = hay.map[idx];
  const last = needle.str[needle.str.length - 1];
  const end = hay.map[idx + needle.str.length - 1] + (raw.codePointAt(hay.map[idx + needle.str.length - 1]) > 0xffff ? 2 : 1);
  void last;
  // Split into per-node sub-ranges: a range inside one text node always wraps
  // (surroundContents throws only when it would cut an element in half).
  let pos = 0;
  const jobs = [];
  for (const n of nodes) {
    const len = n.nodeValue.length;
    const s = Math.max(start - pos, 0), e = Math.min(end - pos, len);
    if (s < e) jobs.push([n, s, e]);
    pos += len;
  }
  jobs.reverse().forEach(([n, s, e]) => {
    const r = document.createRange();
    r.setStart(n, s);
    r.setEnd(n, e);
    const sp = document.createElement("span");
    sp.className = "ann-mark";
    sp.dataset.annId = id;
    sp.title = "annotated — click for the note";
    r.surroundContents(sp);
  });
  return true;
}

function _paintSection() {
  const text = document.getElementById("text");
  const cur = readerState && readerState.cur;
  if (!text || !cur) return;
  text.innerHTML = cur.sec.blocks.map(renderBlock).join("") || `<p class="reader-empty">(empty)</p>`;
  _applyAnnHighlights();
}

function _applyAnnHighlights() {
  const st = readerState;
  const text = document.getElementById("text");
  if (!st || !st.cur || !text) return;
  const items = ANNOT.forWork(st.aid, st.wid).filter((a) => a.section === st.cur.idx);
  const byBlock = new Map();
  items.forEach((a) => {
    if (a.bi == null) return;
    if (!byBlock.has(a.bi)) byBlock.set(a.bi, []);
    byBlock.get(a.bi).push(a);
  });
  byBlock.forEach((list, bi) => {
    const block = text.querySelector(`[data-bi="${bi}"]`);
    if (!block) return;
    list.sort((a, b) => b.quote.length - a.quote.length);   // longest first: it may contain the shorter
    list.forEach((a) => { try { _wrapQuote(block, a.quote, a.id); } catch { /* never break the text */ } });
  });
}

/* ---- the notes tab ---- */
function _notesHtml() {
  const st = readerState;
  if (!st) return "";
  const items = ANNOT.forWork(st.aid, st.wid);
  const bar = `<div class="ann-bar">
      <button class="tool-btn" type="button" data-ann-exp="json">⤓ JSON</button>
      <button class="tool-btn" type="button" data-ann-exp="md">⤓ Markdown</button>
      <button class="tool-btn" type="button" data-ann-imp="1">⤒ import</button>
      ${items.length ? `<button class="tool-btn danger" type="button" data-ann-clear="1">delete all</button>` : ""}
      <input type="file" id="ann-file" accept=".json,application/json" hidden>
    </div>`;
  if (!items.length) {
    return `${bar}<div class="drawer-hint">No notes on this work yet.
      Select a passage in the text and press <b>✎ annotate</b>.</div>`;
  }
  const groups = new Map();
  items.slice().sort((a, b) => (a.section ?? 1e9) - (b.section ?? 1e9))
    .forEach((a) => {
      const k = a.section ?? -1;
      if (!groups.has(k)) groups.set(k, []);
      groups.get(k).push(a);
    });
  const html = [...groups.entries()].map(([sec, list]) => `
    <div class="ann-group">
      <div class="ev-cap">${sec < 0 ? "unplaced" : esc(list[0].section_label || "section " + sec)}</div>
      ${list.map((a) => `<div class="ann-item" data-ann-id="${esc(a.id)}">
        <div class="ann-q greek" ${a.section != null ? `data-ann-goto="${a.section}"` : ""}
          title="${a.section != null ? "go to this passage" : ""}">“${esc(a.quote)}”</div>
        ${a.note ? `<div class="ann-note-body">${esc(a.note)}</div>` : ""}
        ${(a.tags || []).length ? `<div class="ann-tags">${a.tags.map((t) => `<span class="ann-tag">${esc(t)}</span>`).join("")}</div>` : ""}
        <div class="ann-acts">
          <button class="ann-mini" type="button" data-ann-edit="${esc(a.id)}">edit</button>
          <button class="ann-mini" type="button" data-ann-del="${esc(a.id)}">delete</button>
          <span class="muted">${esc((a.created || "").slice(0, 10))}</span>
        </div>
      </div>`).join("")}
    </div>`).join("");
  return bar + html;
}

function _renderNotes() { _drawerBody(_notesHtml()); }

/* ---- exports ---- */
function _download(name, text, mime) {
  const blob = new Blob([text], { type: (mime || "text/plain") + ";charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = name;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}

function _blocksTxt(blocks) {
  const out = [];
  for (const b of blocks) {
    if (b.kind === "head") out.push("", "## " + b.text, "");
    else if (b.kind === "line") out.push((b.n != null ? String(b.n).padStart(5) : "     ") + "  " + b.text);
    else out.push(b.text, "");
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

function _txtHeader(st, sectionLabel) {
  return [
    "# KONI — exported Greek text",
    "# author: " + (st.author || st.aid) + " (" + st.aid + ")",
    "# work: " + (st.title || st.wid) + (st.title_greek ? " / " + st.title_greek : ""),
    "# urn: " + (st.urn || ""),
    "# edition: " + (st.edition || "(as recorded by the app)"),
    sectionLabel ? "# section: " + sectionLabel : null,
    "# exported: " + new Date().toISOString(),
    "# Line numbers are the edition's. The text is the open edition served by",
    "# /api/text; check the Sources list in the app for the scan or edition it came from.",
  ].filter((x) => x != null).join("\n") + "\n";
}

function _annAppendix(items, label) {
  if (!items.length) return "";
  return "\n\n# ---- annotations (" + label + ") ----\n" + items.map((a) =>
    `# [${a.section_label || a.section}] "${a.quote}"\n#   ${a.note || "(no note)"}`
    + ((a.tags || []).length ? `\n#   tags: ${a.tags.join(", ")}` : "")).join("\n");
}

function exportSection() {
  const st = readerState;
  if (!st || !st.cur) { toast("Nothing loaded yet."); return; }
  const label = st.label.get(st.cur.idx) || String(st.cur.idx);
  const items = ANNOT.forWork(st.aid, st.wid).filter((a) => a.section === st.cur.idx);
  const txt = _txtHeader(st, label) + "\n" + _blocksTxt(st.cur.sec.blocks)
    + _annAppendix(items, "this section") + "\n";
  _download(`koni_${st.aid}.${st.wid}.${st.cur.idx}.txt`, txt);
  toast("Section exported (txt).");
}

async function exportWork() {
  const st = readerState;
  if (!st) return;
  const secs = st.sections.filter((s) => s.block_count);
  if (!secs.length) { toast("This work has no text to export."); return; }
  toast(`Exporting ${secs.length} sections…`);
  const parts = [_txtHeader(st, null)];
  for (let i = 0; i < secs.length; i++) {
    const s = secs[i];
    try {
      const sec = await fetchJSON(API(`/text/${st.aid}/${st.wid}/section/${s.index}`));
      parts.push("\n\n" + "# ===== " + (s.label || s.index) + " =====\n\n" + _blocksTxt(sec.blocks));
    } catch (e) {
      parts.push(`\n\n# ===== ${s.label || s.index} — FAILED: ${e.message} =====`);
    }
    toast(`Exporting… ${i + 1}/${secs.length}`);
  }
  parts.push(_annAppendix(ANNOT.forWork(st.aid, st.wid), "whole work"));
  _download(`koni_${st.aid}.${st.wid}.txt`, parts.join("\n") + "\n");
  toast(`Work exported: ${secs.length} sections.`);
}

function _annItemsForExport() {
  const st = readerState;
  return st ? ANNOT.forWork(st.aid, st.wid) : [];
}

function exportAnnotations(fmt) {
  const st = readerState, items = _annItemsForExport();
  if (!st || !items.length) { toast("No notes to export."); return; }
  const base = `koni_notes_${st.aid}.${st.wid}`;
  if (fmt === "md") {
    const lines = [`# Notes — ${st.title || st.wid}`, "",
      `_${st.author || st.aid} · ${st.urn || ""} · exported ${new Date().toISOString().slice(0, 10)}_`, ""];
    items.slice().sort((a, b) => (a.section ?? 1e9) - (b.section ?? 1e9)).forEach((a) => {
      lines.push(`## ${a.section_label || a.section || "unplaced"}`, "",
        `> ${a.quote}`, "", a.note || "_(no note)_",
        (a.tags || []).length ? `\nTags: ${a.tags.map((t) => "`" + t + "`").join(" ")}` : "", "");
    });
    _download(base + ".md", lines.join("\n"), "text/markdown");
  } else {
    _download(base + ".json", JSON.stringify({
      version: 1, exported: new Date().toISOString(),
      work: { aid: st.aid, wid: st.wid, title: st.title, author: st.author, urn: st.urn },
      items,
    }, null, 1), "application/json");
  }
  toast(`${items.length} notes exported (${fmt.toUpperCase()}).`);
}

function importAnnotations(file) {
  const st = readerState;
  if (!st || !file) return;
  const fr = new FileReader();
  fr.onload = () => {
    let d;
    try { d = JSON.parse(String(fr.result)); }
    catch { toast("Not a JSON file."); return; }
    const items = Array.isArray(d) ? d : (Array.isArray(d.items) ? d.items : []);
    if (!items.length) { toast("No notes in that file."); return; }
    const have = new Set(ANNOT.all().map((a) => a.id));
    let n = 0;
    items.forEach((a) => {
      if (!a || !a.quote) return;
      const rec = {
        id: have.has(a.id) ? _annId() : (a.id || _annId()),
        aid: a.aid || st.aid, wid: a.wid || st.wid,
        section: a.section ?? null, section_label: a.section_label || "",
        bi: a.bi ?? null, quote: a.quote, note: a.note || "",
        tags: Array.isArray(a.tags) ? a.tags : [],
        work: a.work || st.title, urn: a.urn || st.urn,
        created: a.created || new Date().toISOString(), modified: a.modified || null,
      };
      if (have.has(rec.id)) return;
      ANNOT.add(rec);
      have.add(rec.id);
      n++;
    });
    _paintSection();
    _refreshCount();
    _renderNotes();
    toast(n ? `${n} notes imported.` : "Nothing new to import.");
  };
  fr.readAsText(file);
}

/* ---- section stepping and shortcuts ---- */
function _stepSection(dir) {
  const st = readerState;
  if (!st || !st.sections.length) return;
  const i = st.sections.findIndex((s) => s.index === (st.cur ? st.cur.idx : -1));
  const next = st.sections[i < 0 ? 0 : i + dir];
  if (!next) { toast(dir > 0 ? "Last section." : "First section."); return; }
  loadSection(st.aid, st.wid, next.index);
}

function _onKey(e) {
  if (/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName) || e.target.isContentEditable) return;
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  if (e.key === "Escape") {
    _closePopover();
    _hideAnnBtn();
    _unmarkWord();
    _closeDrawer();
    return;
  }
  if (!readerState || !document.getElementById("text")) return;
  if (e.key === "[") { e.preventDefault(); _stepSection(-1); }
  else if (e.key === "]") { e.preventDefault(); _stepSection(1); }
}

function _onTextClick(e) {
  const text = document.getElementById("text");
  if (!text || !text.contains(e.target)) return;
  const mark = e.target.closest?.(".ann-mark");
  const sel = document.getSelection();
  if (sel && !sel.isCollapsed) return;      // selecting, not looking up
  if (mark) {                                // an annotated word: show its note
    const a = ANNOT.all().find((x) => x.id === mark.dataset.annId);
    if (a) {
      _openDrawer("notes");
      const el = _drawer()?.querySelector(`[data-ann-id="${a.id}"]`);
      if (el) { el.scrollIntoView({ block: "center", behavior: "smooth" }); el.classList.add("flash"); setTimeout(() => el.classList.remove("flash"), 1200); }
      return;
    }
  }
  const hit = _wordAt(e.clientX, e.clientY);
  if (hit) lookupWord(hit);
}

function _onMouseUp(e) {
  if (_pop && !_pop.hidden) return;
  if (e.target.closest?.("#ann-btn, #ann-pop, #drawer")) return;
  _hideAnnBtn();
  const sel = _selQuote();
  if (!sel) return;
  if (_drawer()?.contains(e.target)) return;
  _showAnnBtn(sel);
}

function _onDelegateClick(e) {
  const t = e.target;
  const hit = (sel) => t.closest?.(sel);
  if (hit("#exp-sec")) return exportSection();
  if (hit("#exp-work")) return exportWork();
  if (hit("#ann-open")) { _openDrawer("notes"); return; }
  if (hit("#drawer-close") || hit("#drawer-close2")) return _closeDrawer();
  const tab = hit(".dtab");
  if (tab) return _drawerTab(tab.dataset.tab);
  if (hit("#ann-btn")) {
    const b = hit("#ann-btn");
    return _openPopover(b._quote || "", b.dataset.bi, b.getBoundingClientRect());
  }
  if (hit("#ann-cancel")) return _closePopover();
  if (hit("#ann-save")) return _saveAnnotation();
  const exp = hit("[data-ann-exp]");
  if (exp) return exportAnnotations(exp.dataset.annExp);
  const imp = hit("[data-ann-imp]");
  if (imp) return document.getElementById("ann-file")?.click();
  const clr = hit("[data-ann-clear]");
  if (clr) {
    const st = readerState;
    if (!st) return;
    if (!confirm("Delete every note on this work? This cannot be undone.")) return;
    ANNOT.write(ANNOT.all().filter((a) => !(a.aid === st.aid && a.wid === st.wid)));
    _paintSection();
    _refreshCount();
    _renderNotes();
    toast("Notes deleted.");
    return;
  }
  const go = hit("[data-ann-goto]");
  if (go) {
    const idx = +go.dataset.annGoto;
    const st = readerState;
    if (!st) return;
    if (st.cur && st.cur.idx === idx) {
      _drawer()?.querySelector(`[data-ann-id="${go.closest("[data-ann-id]")?.dataset.annId}"]`)
        ?.scrollIntoView({ block: "center", behavior: "smooth" });
    } else loadSection(st.aid, st.wid, idx);
    return;
  }
  const ed = hit("[data-ann-edit]");
  if (ed) {
    const a = ANNOT.all().find((x) => x.id === ed.dataset.annEdit);
    if (a) _openPopover(a.quote, a.bi, ed.getBoundingClientRect(), a.id);
    return;
  }
  const del = hit("[data-ann-del]");
  if (del) {
    const a = ANNOT.all().find((x) => x.id === del.dataset.annDel);
    if (a && confirm("Delete this note?\n\n“" + a.quote.slice(0, 90) + "”")) {
      ANNOT.remove(a.id);
      _paintSection();
      _refreshCount();
      _renderNotes();
      toast("Note deleted.");
    }
    return;
  }
}

document.addEventListener("click", _onDelegateClick);
document.addEventListener("mouseup", _onMouseUp);
document.addEventListener("keydown", _onKey);
document.addEventListener("change", (e) => {
  if (e.target.id === "ann-file" && e.target.files?.[0]) {
    importAnnotations(e.target.files[0]);
    e.target.value = "";
  }
});

