.greek-text .line .ltext { white-space: pre-wrap; }

/* ---- reader toolbar (export / notes / hints) ---- */
.reader-tools {
  display: flex; align-items: center; gap: .4rem; flex-wrap: wrap;
  margin: 0 0 1rem; padding-bottom: .6rem;
  border-bottom: 1px solid var(--rule);
}
.tool-btn {
  font-family: var(--font-meta); font-size: .68rem; letter-spacing: .06em;
  text-transform: uppercase; color: var(--text-soft);
  background: none; border: 1px solid var(--rule); border-radius: var(--radius);
  padding: .22rem .5rem; cursor: pointer; transition: color .12s, border-color .12s;
}
.tool-btn:hover { color: var(--accent); border-color: var(--accent-soft); }
.tool-btn.danger:hover { color: var(--accent); border-color: var(--accent); }
.tool-hint {
  font-family: var(--font-meta); font-size: .64rem; color: var(--text-faint);
  letter-spacing: .04em; margin-left: auto;
}
.tool-hint kbd {
  font-family: var(--font-meta); font-size: .64rem;
  border: 1px solid var(--rule-strong); border-radius: 2px; padding: 0 .2rem;
}
@media (max-width: 900px) { .tool-hint { display: none; } }

/* The word last looked up. A tint, not an underline: the text is the object of
   study and must not start looking like a link. */
.dict-active { background: var(--bg-soft); box-shadow: 0 0 0 1px var(--rule); border-radius: 2px; }

/* An annotated passage. Dotted underline on hover only — the highlight is a
   quiet marker that a note exists, not a permanent claim on the words. */
.ann-mark {
  border-bottom: 1px dotted var(--accent-soft); cursor: pointer;
  background: rgba(122, 46, 46, .05);
}
.ann-mark:hover { background: rgba(122, 46, 46, .12); }

/* ---- the drawer (dictionary + notes) ---- */
.drawer {
  position: fixed; top: 4.2rem; right: 1rem; bottom: 1rem;
  width: min(26rem, calc(100vw - 2rem)); z-index: 30;
  display: flex; flex-direction: column;
  background: var(--bg-elev); border: 1px solid var(--rule-strong);
  border-radius: var(--radius);
}
@media (min-width: 1101px) {
  /* On a wide screen the drawer takes its own room instead of covering the
     text: the pane gives up exactly the drawer's width. */
  body.drawer-open .reader-pane { padding-right: 27rem; }
  body.drawer-open .greek-text { max-width: 44rem; }
}
.drawer-tabs {
  display: flex; align-items: center; gap: .5rem;
  padding: .5rem .7rem; border-bottom: 1px solid var(--rule);
}
.dtab {
  font-family: var(--font-meta); font-size: .68rem; letter-spacing: .1em;
  text-transform: uppercase; background: none; border: none; cursor: pointer;
  color: var(--text-faint); padding: .1rem 0; border-bottom: 1px solid transparent;
}
.dtab:hover { color: var(--text); }
.dtab.active { color: var(--accent); border-bottom-color: var(--accent); }
.drawer-tabs .ev-close { margin-left: auto; }
.drawer-body { overflow: auto; padding: .8rem .9rem 1.2rem; }
.drawer-hint {
  font-family: var(--font-meta); font-size: .7rem; line-height: 1.7;
  color: var(--text-faint); padding: 1rem .2rem;
}
.dict-head { display: flex; align-items: baseline; gap: .5rem; flex-wrap: wrap; }
.dict-head b { font-size: 1.3rem; }
.dict-head .ev-close { margin-left: auto; }
.dict-lab {
  font-family: var(--font-meta); font-size: .6rem; letter-spacing: .08em;
  text-transform: uppercase; color: var(--text-faint);
}
.dict-form { color: var(--accent); font-size: 1.05rem; margin: .2rem 0 .3rem; }
.dict-how { font-size: .78rem; color: var(--text-faint); margin-bottom: .7rem; }
.dict-gloss { font-size: .95rem; line-height: 1.6; margin: 0 0 .6rem; }
.dict-gloss.dict-note { color: var(--text-soft); font-size: .85rem; }
.dict-miss { color: var(--accent); margin: .3rem 0; }
.dict-forms { display: flex; flex-wrap: wrap; gap: .3rem; font-size: .86rem; }
.dict-forms span {
  border: 1px solid var(--rule); border-radius: var(--radius); padding: 0 .3rem;
}
.dict-alt { margin: 0; padding-left: 1rem; font-size: .84rem; }
.dict-occ { margin: 0; padding-left: 1rem; font-size: .82rem; }
.dict-out { margin-top: 1rem; }
.dict-src { margin-top: 1rem; font-size: .74rem; color: var(--text-faint); }
.dict-src > summary { cursor: pointer; font-family: var(--font-meta); letter-spacing: .1em; text-transform: uppercase; font-size: .62rem; }
.dict-src p { margin: .5rem 0 0; line-height: 1.5; }

/* ---- notes tab ---- */
.ann-bar { display: flex; gap: .35rem; flex-wrap: wrap; margin-bottom: .8rem; }
.ann-group { margin-bottom: .9rem; }
.ann-item {
  border-left: 2px solid var(--rule); padding: .2rem 0 .5rem .6rem; margin-bottom: .5rem;
  transition: border-color .15s;
}
.ann-item.flash { border-left-color: var(--accent); }
.ann-q {
  font-family: var(--font-greek); font-size: .92rem; line-height: 1.5; cursor: pointer;
}
.ann-q:hover { color: var(--accent); }
.ann-note-body { font-size: .84rem; color: var(--text-soft); margin: .25rem 0; line-height: 1.5; }
.ann-tags { display: flex; gap: .25rem; flex-wrap: wrap; margin: .2rem 0; }
.ann-tag {
  font-family: var(--font-meta); font-size: .58rem; letter-spacing: .08em;
  text-transform: uppercase; color: var(--accent);
  border: 1px solid var(--rule); border-radius: var(--radius); padding: 0 .25rem;
}
.ann-acts { display: flex; gap: .4rem; align-items: baseline; }
.ann-mini {
  font-family: var(--font-meta); font-size: .62rem; letter-spacing: .06em;
  text-transform: uppercase; background: none; color: var(--text-faint);
  border: none; cursor: pointer; padding: 0;
}
.ann-mini:hover { color: var(--accent); }
.ann-acts .muted { color: var(--text-faint); font-size: .64rem; margin-left: auto; }

/* ---- floating annotate button + popover ---- */
.ann-btn {
  position: fixed; z-index: 40;
  font-family: var(--font-meta); font-size: .66rem; letter-spacing: .08em;
  text-transform: uppercase; cursor: pointer;
  color: var(--bg-elev); background: var(--accent);
  border: none; border-radius: var(--radius); padding: .25rem .5rem;
}
.ann-btn[hidden] { display: none; }
.ann-pop {
  position: fixed; z-index: 41; width: min(22rem, calc(100vw - 1rem));
  background: var(--bg-elev); border: 1px solid var(--rule-strong);
  border-radius: var(--radius); padding: .6rem; display: flex; flex-direction: column; gap: .4rem;
}
.ann-pop[hidden] { display: none; }
.ann-quote {
  font-size: .92rem; line-height: 1.5; color: var(--text-soft);
  max-height: 6rem; overflow: auto;
  border-left: 2px solid var(--rule); padding-left: .5rem;
}
.ann-pop textarea, .ann-pop input {
  font-family: var(--font-ui); font-size: .85rem; color: var(--text);
  background: var(--bg); border: 1px solid var(--rule); border-radius: var(--radius);
  padding: .35rem .45rem; width: 100%; resize: vertical;
}
.ann-pop textarea:focus, .ann-pop input:focus { outline: 1px solid var(--accent-soft); }
.ann-actions { display: flex; align-items: center; gap: .4rem; }
.ann-actions .muted { color: var(--accent); font-size: .7rem; }

