  font-family: var(--font-meta); font-size: .66rem; letter-spacing: .08em;
  text-transform: uppercase; cursor: pointer;
  color: var(--bg-elev); background: var(--accent);
  border: none; border-radius: var(--radius); padding: .25rem .5rem;
}
.ann-btn[hidden] { display: none; }
.ann-pop {
  position: fixed; z-index: 41; width: min(22rem, calc(100vw - 1rem));
  background: var(--bg-elev); border: 1px solid var(--rule-strong);
  border-radius: var(--radius); padding: .6rem; display: flex; flex-direction: column; gap: .4rem;
}
.ann-pop[hidden] { display: none; }
.ann-quote {
  font-size: .92rem; line-height: 1.5; color: var(--text-soft);
  max-height: 6rem; overflow: auto;
  border-left: 2px solid var(--rule); padding-left: .5rem;
}
.ann-pop textarea, .ann-pop input {
  font-family: var(--font-ui); font-size: .85rem; color: var(--text);
  background: var(--bg); border: 1px solid var(--rule); border-radius: var(--radius);
  padding: .35rem .45rem; width: 100%; resize: vertical;
}
.ann-pop textarea:focus, .ann-pop input:focus { outline: 1px solid var(--accent-soft); }
.ann-actions { display: flex; align-items: center; gap: .4rem; }
.ann-actions .muted { color: var(--accent); font-size: .7rem; }

