  key("Escape");
  ck(true, "Escape is handled");
  delete els["text"];
}
{
  // No reader on screen: the shortcut handler must not act on a stale state.
  R.setState(null);
  loadCalls.length = 0;
  els["text"] = makeEl({});
  R._onKey({ key: "]", target: { tagName: "BODY" } });
