function _collapse(s) {
  const str = [];
  const map = [];
  let sp = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (/\s/.test(ch)) { sp = true; continue; }
    // The collapsed space points at the whitespace it replaced, not at the
    // character after it: `map` must stay strictly increasing, and every index
    // in it must name the character it stands for, or a highlight computed
    // through the map lands one character off.
    if (sp && str.length) { str.push(" "); map.push(i - 1); }
    sp = false;
    str.push(ch);
    map.push(i);
  }
  return { str: str.join(""), map };
}

