function _blocksTxt(blocks) {
  const out = [];
  for (const b of blocks) {
    if (b.kind === "head") out.push("", "## " + b.text, "");
    else if (b.kind === "line") out.push((b.n != null ? String(b.n).padStart(5) : "     ") + "  " + b.text);
    else out.push(b.text, "");
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

input.new_string:
function _blocksTxt(blocks) {
  const out = [];
  let prev = null;
  for (const b of blocks) {
    if (b.kind === "head") out.push("", "## " + b.text, "");
    else if (b.kind === "line") out.push((b.n != null ? String(b.n).padStart(5) : "     ") + "  " + b.text);
    else {
      // Prose after verse (or after another paragraph) needs its own blank
      // line, or the edition's line breaks read as the author's sentences.
      if (prev != null && prev.kind !== "para" && prev.kind !== "head") out.push("");
      out.push(b.text, "");
    }
    prev = b;
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trim();
}

