function _drawer() { return document.getElementById("drawer"); }

function _openDrawer(tab) {
  const d = _drawer();
  if (!d) return;
  d.hidden = false;
  document.body.classList.add("drawer-open");
  if (tab) _drawerTab(tab);
  else _drawerTab(d.querySelector(".dtab.active")?.dataset.tab || "dict");
}

function _closeDrawer() {
  const d = _drawer();
  if (d) d.hidden = true;
  document.body.classList.remove("drawer-open");
}

function _drawerTab(tab) {
  const d = _drawer();
  if (!d) return;
  d.querySelectorAll(".dtab").forEach((b) => b.classList.toggle("active", b.dataset.tab === tab));
  if (tab === "notes") { _renderNotes(); return; }
  if (!d.dataset.dictShown) {
    d.dataset.dictShown = "1";
    _drawerBody(`<div class="drawer-hint">Click a word in the text to look it up.</div>`);
  }
}

